import { createRoute, z } from '@hono/zod-openapi'

const AnnotationDisplayBoundsSchema = z
  .object({
    height: z
      .float64()
      .exactOptional()
      .openapi({ description: "The annotation's height on the canvas." }),
    width: z
      .float64()
      .exactOptional()
      .openapi({ description: "The annotation's width on the canvas." }),
    x: z
      .float64()
      .exactOptional()
      .openapi({ description: "The annotation's horizontal canvas coordinate." }),
    y: z
      .float64()
      .exactOptional()
      .openapi({ description: "The annotation's vertical canvas coordinate." }),
  })
  .openapi({
    description: 'Canvas coordinates and dimensions for an annotation on the workflow canvas.',
    required: [],
  })
  .openapi('AnnotationDisplayBounds')

const AnnotationDisplaySchema = z
  .object({ bounds: AnnotationDisplayBoundsSchema.exactOptional() })
  .openapi({
    description: "The annotation's position and size on the workflow canvas.",
    required: [],
  })
  .openapi('AnnotationDisplay')

const AnnotationMarkdownTextAnnotationSchema = z
  .object({
    text: z
      .string()
      .max(3000)
      .exactOptional()
      .openapi({ description: "The annotation's Markdown content." }),
  })
  .openapi({ description: 'Markdown content displayed in an annotation.', required: [] })
  .openapi('AnnotationMarkdownTextAnnotation')

type AnnotationType = {
  display: z.infer<typeof AnnotationDisplaySchema>
  id: string
  markdownTextAnnotation: z.infer<typeof AnnotationMarkdownTextAnnotationSchema>
}

const AppBuilderEventNameSchema = z
  .enum([
    'pageChange',
    'tableRowClick',
    '_tableRowButtonClick',
    'change',
    'submit',
    'click',
    'toggleOpen',
    'close',
    'open',
    'executionFinished',
  ])
  .openapi({
    description: 'The triggering action for the event.',
    example: 'click',
    'x-enum-varnames': [
      'PAGECHANGE',
      'TABLEROWCLICK',
      'TABLEROWBUTTONCLICK',
      'CHANGE',
      'SUBMIT',
      'CLICK',
      'TOGGLEOPEN',
      'CLOSE',
      'OPEN',
      'EXECUTIONFINISHED',
    ],
  })
  .openapi('AppBuilderEventName')

const AppBuilderEventTypeSchema = z
  .enum([
    'custom',
    'setComponentState',
    'triggerQuery',
    'openModal',
    'closeModal',
    'openUrl',
    'downloadFile',
    'setStateVariableValue',
  ])
  .openapi({
    description: 'The response to the event.',
    example: 'triggerQuery',
    'x-enum-varnames': [
      'CUSTOM',
      'SETCOMPONENTSTATE',
      'TRIGGERQUERY',
      'OPENMODAL',
      'CLOSEMODAL',
      'OPENURL',
      'DOWNLOADFILE',
      'SETSTATEVARIABLEVALUE',
    ],
  })
  .openapi('AppBuilderEventType')

type AppBuilderEventType = {
  name?: z.infer<typeof AppBuilderEventNameSchema>
  type?: z.infer<typeof AppBuilderEventTypeSchema>
}

const AnalysisPositionSchema = z
  .object({
    col: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'The column number in the source file (1-based).',
        example: 5,
      }),
    line: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'The line number in the source file (1-based).',
        example: 10,
      }),
  })
  .openapi({
    description: 'A position in source code, identified by line and column numbers.',
    required: ['line', 'col'],
  })
  .openapi('AnalysisPosition')

type AstNodeType = {
  ast_type: string
  children: AstNodeType[] | null
  end: z.infer<typeof AnalysisPositionSchema>
  field_name?: string
  start: z.infer<typeof AnalysisPositionSchema>
}

const AppBuilderEventSchema: z.ZodType<AppBuilderEventType> = z
  .object({
    name: AppBuilderEventNameSchema.exactOptional(),
    type: AppBuilderEventTypeSchema.exactOptional(),
  })
  .catchall(z.any())
  .openapi({
    description: 'An event on a UI component that triggers a response or action in an app.',
  })
  .openapi('AppBuilderEvent')

const ComponentPropertiesSchema: z.ZodType<ComponentPropertiesType> = z
  .lazy(() =>
    z
      .object({
        children: z
          .array(ComponentSchema)
          .exactOptional()
          .openapi({ description: 'The child components of the UI component.' }),
        isVisible: ComponentPropertiesIsVisibleSchema.exactOptional(),
      })
      .catchall(z.any())
      .openapi({
        description:
          'Properties of a UI component. Different component types can have their own additional unique properties. See the [components documentation](https://docs.datadoghq.com/service_management/app_builder/components/) for more detail on each component type and its properties.',
      }),
  )
  .openapi('ComponentProperties')

type ComponentTypeType =
  | 'table'
  | 'textInput'
  | 'textArea'
  | 'button'
  | 'text'
  | 'select'
  | 'modal'
  | 'schemaForm'
  | 'checkbox'
  | 'tabs'
  | 'vegaChart'
  | 'radioButtons'
  | 'numberInput'
  | 'fileInput'
  | 'jsonInput'
  | 'gridCell'
  | 'dateRangePicker'
  | 'search'
  | 'container'
  | 'calloutValue'

const ComponentTypeSchema: z.ZodType<ComponentTypeType> = z
  .enum([
    'table',
    'textInput',
    'textArea',
    'button',
    'text',
    'select',
    'modal',
    'schemaForm',
    'checkbox',
    'tabs',
    'vegaChart',
    'radioButtons',
    'numberInput',
    'fileInput',
    'jsonInput',
    'gridCell',
    'dateRangePicker',
    'search',
    'container',
    'calloutValue',
  ])
  .openapi({
    description: 'The UI component type.',
    example: 'text',
    'x-enum-varnames': [
      'TABLE',
      'TEXTINPUT',
      'TEXTAREA',
      'BUTTON',
      'TEXT',
      'SELECT',
      'MODAL',
      'SCHEMAFORM',
      'CHECKBOX',
      'TABS',
      'VEGACHART',
      'RADIOBUTTONS',
      'NUMBERINPUT',
      'FILEINPUT',
      'JSONINPUT',
      'GRIDCELL',
      'DATERANGEPICKER',
      'SEARCH',
      'CONTAINER',
      'CALLOUTVALUE',
    ],
  })
  .openapi('ComponentType')

type ComponentType = {
  events?: z.infer<typeof AppBuilderEventSchema>[]
  id?: string | null
  name: string
  properties: z.infer<typeof ComponentPropertiesSchema>
  type: z.infer<typeof ComponentTypeSchema>
}

const ComponentSchema: z.ZodType<ComponentType> = z
  .lazy(() =>
    z
      .object({
        events: z
          .array(AppBuilderEventSchema)
          .exactOptional()
          .openapi({ description: 'Events to listen for on the UI component.' }),
        id: z
          .string()
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'The ID of the UI component. This property is deprecated; use `name` to identify individual components instead.',
          }),
        name: z
          .string()
          .openapi({
            description:
              'A unique identifier for this UI component. This name is also visible in the app editor.',
            example: '',
          }),
        properties: ComponentPropertiesSchema,
        type: ComponentTypeSchema,
      })
      .openapi({
        description:
          '[Definition of a UI component in the app](https://docs.datadoghq.com/service_management/app_builder/components/)',
        required: ['name', 'type', 'properties'],
      }),
  )
  .openapi('Component')

type ComponentPropertiesIsVisibleType = boolean | string

const ComponentPropertiesIsVisibleSchema: z.ZodType<ComponentPropertiesIsVisibleType> = z
  .xor([
    z.boolean(),
    z
      .string()
      .openapi({
        description:
          'If this is a string, it must be a valid JavaScript expression that evaluates to a boolean.',
        example: '${true}',
      }),
  ])
  .openapi({
    description:
      'Whether the UI component is visible. If this is a string, it must be a valid JavaScript expression that evaluates to a boolean.',
  })
  .openapi('ComponentPropertiesIsVisible')

type ComponentPropertiesType = {
  children?: z.infer<typeof ComponentSchema>[]
  isVisible?: z.infer<typeof ComponentPropertiesIsVisibleSchema>
}

