const DeploymentRuleOptionsMonitorIdSchema = z
  .strictObject({
    groups: z
      .array(z.string().min(1).openapi({ description: 'An exact monitor group name.' }))
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .openapi({
        description:
          'The exact monitor group names to evaluate. An empty array evaluates all groups.',
        example: [],
      }),
    id: z
      .string()
      .regex(/^[1-9][0-9]*$/)
      .openapi({ description: "The monitor's decimal ID.", example: '123456' }),
  })
