const SlackTriggerSchema = z
  .object({
    reactionTriggers: z
      .array(SlackReactionConfigSchema)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional()
      .openapi({ description: 'Slack emoji reactions that trigger the workflow.' }),
  })
  .openapi({
    description: 'Trigger a workflow from Slack. The workflow must be published.',
    required: [],
  })
  .openapi('SlackTrigger')

