const HistoricalJobQuerySchema = z
  .object({
    additionalFilters: z
      .string()
      .exactOptional()
      .openapi({ description: 'Additional filters appended to the query at evaluation time.' }),
    aggregation: SecurityMonitoringRuleQueryAggregationSchema.exactOptional(),
    correlatedByFields: z
      .array(z.string().openapi({ description: 'Field.' }))
      .exactOptional()
      .openapi({
        description: 'Fields used to correlate results across queries in sequence detection rules.',
      }),
    correlatedQueryIndex: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64().min(0n).max(9n),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        minimum: 0,
        maximum: 9,
        description:
          'Zero-based index of the query to correlate with in sequence detection rules. Up to 10 queries are supported, so valid values are 0 to 9.',
      }),
    customQueryExtension: z
      .string()
      .exactOptional()
      .openapi({ description: 'Custom query extension used to refine the base query.' }),
    dataSource: SecurityMonitoringStandardDataSourceSchema.exactOptional(),
    datasetIds: z
      .array(z.string().openapi({ description: 'Dataset ID.' }))
      .exactOptional()
      .openapi({ description: 'IDs of reference datasets used by this query.' }),
    distinctFields: z
      .array(z.string().openapi({ description: 'Field.' }))
      .exactOptional()
      .openapi({ description: 'Field for which the cardinality is measured. Sent as an array.' }),
    groupByFields: z
      .array(z.string().openapi({ description: 'Field.' }))
      .exactOptional()
      .openapi({ description: 'Fields to group by.' }),
    hasOptionalGroupByFields: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'When false, events without a group-by value are ignored by the query. When true, events with missing group-by fields are processed with `N/A`, replacing the missing values.',
        example: false,
      }),
    index: z
      .string()
      .exactOptional()
      .openapi({ description: 'Index used to load the data for this query.' }),
    indexes: z
      .array(z.string().openapi({ description: 'Index name.' }))
      .exactOptional()
      .openapi({
        description:
          'Indexes used to load the data for this query. Mutually exclusive with `index`.',
      }),
    metrics: z
      .array(z.string().openapi({ description: 'Field.' }))
      .exactOptional()
      .openapi({
        description:
          'Group of target fields to aggregate over when using the sum, max, geo data, or new value aggregations. The sum, max, and geo data aggregations only accept one value in this list, whereas the new value aggregation accepts up to five values.',
      }),
    name: z.string().exactOptional().openapi({ description: 'Name of the query.' }),
    query: z
      .string()
      .exactOptional()
      .openapi({ description: 'Query to run on logs.', example: 'a > 3' }),
    queryLanguage: z
      .string()
      .exactOptional()
      .openapi({ description: 'Language used to parse the query string.' }),
  })
  .openapi({
    description: 'Query for selecting logs analyzed by the historical job.',
    required: [],
  })
  .openapi('HistoricalJobQuery')

