const JobDefinitionSchema = z
  .object({
    calculatedFields: z
      .array(CalculatedFieldSchema)
      .exactOptional()
      .openapi({ description: 'Calculated fields.' }),
    cases: z
      .array(SecurityMonitoringRuleCaseCreateSchema)
      .max(10)
      .openapi({
        description: 'Cases used for generating job results. Up to 10 cases are allowed.',
      }),
    from: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'Starting time of data analyzed by the job.',
        example: 1729843470000,
      }),
    groupSignalsBy: z
      .array(z.string().openapi({ description: 'Field to group by.' }))
      .exactOptional()
      .openapi({
        description:
          'Additional grouping to perform on top of the existing groups in the query section. Must be a subset of the existing groups.',
        example: ['service'],
      }),
    index: z
      .string()
      .openapi({ description: 'Index used to load the data.', example: 'cloud_siem' }),
    message: z
      .string()
      .openapi({
        description: 'Message for generated results.',
        example: 'A large number of failed login attempts.',
      }),
    name: z
      .string()
      .openapi({ description: 'Job name.', example: 'Excessive number of failed attempts.' }),
    options: HistoricalJobOptionsSchema.exactOptional(),
    queries: z
      .array(HistoricalJobQuerySchema)
      .max(10)
      .openapi({
        description:
          'Queries for selecting logs analyzed by the job. Up to 10 queries are allowed.',
      }),
    referenceTables: z
      .array(SecurityMonitoringReferenceTableSchema)
      .exactOptional()
      .openapi({ description: 'Reference tables used in the queries.' }),
    tags: z
      .array(z.string().openapi({ description: 'A tag string in `key:value` format.' }))
      .exactOptional()
      .openapi({ description: 'Tags for generated signals.' }),
    thirdPartyCases: z
      .array(SecurityMonitoringThirdPartyRuleCaseCreateSchema)
      .max(10)
      .exactOptional()
      .openapi({
        description:
          'Cases for generating results from third-party detection method. Only available for third-party detection method. Up to 10 cases are allowed.',
        example: [],
      }),
    to: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'Ending time of data analyzed by the job.',
        example: 1729847070000,
      }),
    type: z.string().exactOptional().openapi({ description: 'Job type.' }),
  })
  .openapi({
    description: 'Definition of a historical job.',
    required: ['from', 'to', 'index', 'name', 'cases', 'queries', 'message'],
  })
  .openapi('JobDefinition')

