const IncidentUserDefinedFieldListMetaSchema = z
  .object({
    offset: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'The offset of the current page.',
        example: 0,
      }),
    size: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'The total number of items in the current page.',
        example: 5,
      }),
  })
  .openapi({
    description: 'Pagination metadata for the user-defined field list response.',
    required: [],
  })
  .openapi('IncidentUserDefinedFieldListMeta')

