const LLMObsExperimentDataAttributesRequestSchema = z
  .object({
    config: z
      .record(z.string(), z.any())
      .exactOptional()
      .openapi({ description: 'Configuration parameters for the experiment.' }),
    dataset_id: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Identifier of the dataset used in this experiment.',
        example: '9f64e5c7-dc5a-45c8-a17c-1b85f0bec97d',
      }),
    dataset_version: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description:
          'Version of the dataset to use. Defaults to the current version if not specified.',
      }),
    description: z
      .string()
      .exactOptional()
      .openapi({ description: 'Description of the experiment.' }),
    ensure_unique: z
      .boolean()
      .exactOptional()
      .openapi({
        description: 'Whether to ensure the experiment name is unique. Defaults to `true`.',
      }),
    metadata: z
      .record(z.string(), z.any())
      .exactOptional()
      .openapi({ description: 'Arbitrary metadata associated with the experiment.' }),
    name: z
      .string()
      .openapi({ description: 'Name of the experiment.', example: 'My Experiment v1' }),
    parent_experiment_id: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Identifier of the parent (baseline) experiment this experiment is run against.',
        example: '3fd6b5e0-8910-4b1c-a7d0-5b84de329012',
      }),
    project_id: z
      .string()
      .openapi({
        description: 'Identifier of the project this experiment belongs to.',
        example: 'a33671aa-24fd-4dcd-9b33-a8ec7dde7751',
      }),
    run_count: z
      .int32()
      .max(2147483647)
      .exactOptional()
      .openapi({ description: 'Number of runs configured for this experiment.' }),
  })
  .openapi({
    description: 'Attributes for creating an Agent Observability experiment.',
    required: ['project_id', 'name'],
  })
  .openapi('LLMObsExperimentDataAttributesRequest')

