const LLMObsPromptDataAttributesSchema = z
  .object({
    author: z
      .string()
      .exactOptional()
      .openapi({ description: 'UUID of the user who authored the prompt.' }),
    created_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'Timestamp when the prompt was created.' }),
    created_from: z
      .string()
      .openapi({
        description:
          'Source that created the prompt, such as `ui-registry`, `sdk-registry`, or `sdk-instrumentation`.',
        example: 'sdk-registry',
      }),
    datasets: z
      .array(LLMObsPromptDatasetSchema)
      .exactOptional()
      .openapi({ description: 'Datasets observed in runs associated with this prompt.' }),
    description: z.string().exactOptional().openapi({ description: 'Description of the prompt.' }),
    extracted_from: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Source prompt from which this prompt was extracted, when applicable.',
      }),
    in_registry: z
      .boolean()
      .openapi({
        description:
          'Whether the prompt is a registry entry (as opposed to a code-discovered prompt).',
        example: true,
      }),
    last_seen_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'Timestamp of the most recent observed run of this prompt.' }),
    last_version_created_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description: 'Timestamp when the most recent version of the prompt was created.',
      }),
    ml_app: z
      .string()
      .exactOptional()
      .openapi({ description: 'The ML application this prompt is associated with.' }),
    ml_apps: z
      .array(z.string())
      .exactOptional()
      .openapi({ description: 'ML applications observed running this prompt.' }),
    num_versions: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'Number of versions of the prompt.',
        example: 2,
      }),
    prompt_id: z
      .string()
      .openapi({
        description: 'Customer-provided identifier of the prompt.',
        example: 'customer-support-assistant',
      }),
    source: LLMObsPromptResponseSourceSchema,
    tags: z
      .array(z.string())
      .exactOptional()
      .openapi({ description: 'Tags observed on runs of this prompt.' }),
    title: z.string().exactOptional().openapi({ description: 'Title of the prompt.' }),
  })
  .openapi({
    description:
      'Attributes of an Agent Observability prompt registry entry. Prompt list and metadata-update responses omit complete template and configuration data.',
    required: ['prompt_id', 'source', 'num_versions', 'in_registry', 'created_from'],
  })
  .openapi('LLMObsPromptDataAttributes')

