const LogsArchiveCreateRequestDestinationSchema = z
  .xor([
    LogsArchiveDestinationAzureSchema,
    LogsArchiveDestinationGCSSchema,
    LogsArchiveDestinationS3Schema,
  ])
  .openapi({ description: "An archive's destination." })
  .openapi('LogsArchiveCreateRequestDestination')

const LogsArchiveCreateRequestAttributesSchema = z
  .object({
    compression_method: LogsArchiveAttributesCompressionMethodSchema.exactOptional(),
    destination: LogsArchiveCreateRequestDestinationSchema,
    include_tags: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'To store the tags in the archive, set the value "true".\nIf it is set to "false", the tags will be deleted when the logs are sent to the archive.',
        example: false,
      }),
    lookup_attributes: z
      .array(z.string().openapi({ description: 'A lookup attribute name.' }))
      .exactOptional()
      .openapi({
        description: 'An array of attributes to use as lookup keys for the archive.',
        example: ['trace_id', 'user_id'],
      }),
    name: z.string().openapi({ description: 'The archive name.', example: 'Nginx Archive' }),
    partitioning_attributes: z
      .array(z.string().openapi({ description: 'A partition attribute name.' }))
      .exactOptional()
      .openapi({
        description:
          'An array of attributes to use as partition keys for the archive. The attribute used most frequently for querying should be first.',
        example: ['service', 'status'],
      }),
    query: z
      .string()
      .openapi({
        description:
          'The archive query/filter. Logs matching this query are included in the archive.',
        example: 'source:nginx',
      }),
    rehydration_max_scan_size_in_gb: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .nullable()
      .exactOptional()
      .openapi({
        type: ['integer', 'null'],
        format: 'int64',
        description: 'Maximum scan size for rehydration from this archive.',
        example: 100,
      }),
    rehydration_tags: z
      .array(z.string().openapi({ description: 'A given tag in the `<KEY>:<VALUE>` format.' }))
      .exactOptional()
      .openapi({
        description: 'An array of tags to add to rehydrated logs from an archive.',
        example: ['team:intake', 'team:app'],
      }),
  })
  .openapi({
    description: 'The attributes associated with the archive.',
    required: ['name', 'query', 'destination'],
  })
  .openapi('LogsArchiveCreateRequestAttributes')

