const MatchingSignalAttributesSchema = z
  .object({
    event_tracker_id: z
      .string()
      .openapi({
        description:
          'The tracker ID linking the signal back to the originating event. Distinct from `id`, which identifies the matching signal itself.',
        example: 'AAAAAWgOAX0mtsWfeQAAAABzX1RyYWNrZXJfMTIzNDU2Nzg5MA',
      }),
    severity: z.string().openapi({ description: 'The severity of the signal.', example: 'high' }),
    title: z
      .string()
      .openapi({
        description: 'The title of the signal.',
        example: 'Unusual login activity detected',
      }),
    trigger_time_ms: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'The Unix timestamp (in milliseconds) at which the signal was triggered.',
        example: 1707393746000,
      }),
  })
  .openapi({
    description: 'Attributes of a matching security signal.',
    required: ['event_tracker_id', 'severity', 'title', 'trigger_time_ms'],
  })
  .openapi('MatchingSignalAttributes')

