const SummarizedSpanSchema: z.ZodType<SummarizedSpanType> = z
  .lazy(() =>
    z
      .object({
        children: z
          .array(SummarizedSpanSchema)
          .openapi({
            description: 'The child spans of this node in the pruned tree.',
            example: [],
          }),
        durationSeconds: z
          .float64()
          .openapi({ description: 'The duration of the span, in seconds.', example: 0.5 }),
        endTime: z.iso
          .datetime({ offset: true })
          .openapi({
            description: 'The end time of the span, in RFC3339 format.',
            example: '2026-05-27T12:00:00.5Z',
          }),
        error: APMSpanErrorFlagSchema,
        hidden_child_spans_count: z
          .int32()
          .max(2147483647)
          .openapi({
            description:
              'The number of child spans that were pruned from this node when summarizing the trace.',
            example: 0,
          }),
        meta: z
          .record(z.string(), z.string())
          .openapi({
            description: 'String-valued tags attached to the span.',
            example: { env: 'production' },
          }),
        metrics: z
          .record(z.string(), z.float64())
          .openapi({
            description: 'Numeric metrics attached to the span.',
            example: { 'http.status_code': 200 },
          }),
        name: z
          .string()
          .openapi({ description: 'The operation name of the span.', example: 'web.request' }),
        parentID: z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64(),
          )
          .openapi({
            type: 'integer',
            format: 'int64',
            description: 'The ID of the parent span, or `0` when the span is the trace root.',
            example: 0,
          }),
        resource: z
          .string()
          .openapi({
            description: 'The resource that the span describes.',
            example: 'GET /products',
          }),
        service: z
          .string()
          .openapi({
            description: 'The name of the service that emitted the span.',
            example: 'web-store',
          }),
        spanID: z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64(),
          )
          .openapi({
            type: 'integer',
            format: 'int64',
            description: 'The span ID, as an unsigned 64-bit integer.',
            example: 9876543210987655000,
          }),
        span_kind: z
          .string()
          .openapi({
            description:
              'The OpenTelemetry span kind, for example `INTERNAL`, `SERVER`, `CLIENT`,\n`PRODUCER`, or `CONSUMER`.',
            example: 'SERVER',
          }),
        startTime: z.iso
          .datetime({ offset: true })
          .openapi({
            description: 'The start time of the span, in RFC3339 format.',
            example: '2026-05-27T12:00:00Z',
          }),
      })
      .openapi({
        description: 'A node in the pruned trace tree.',
        required: [
          'service',
          'name',
          'resource',
          'parentID',
          'spanID',
          'startTime',
          'endTime',
          'durationSeconds',
          'error',
          'meta',
          'metrics',
          'span_kind',
          'hidden_child_spans_count',
          'children',
        ],
      }),
  )
  .openapi('SummarizedSpan')

