const SeverityModifierRuleActionSchema = z
  .xor([SeverityModifierRuleSetActionSchema, SeverityModifierRuleShiftActionSchema])
  .openapi({
    description:
      "The action to take when a severity modifier rule matches a finding. This is a discriminated union on `type`: `set` assigns a fixed severity, while `shift` moves the severity up or down by one rank.\n\nA severity modifier rule's `rule.query` must not filter on `@severity` or on the `@severity_details.user_adjusted.*` namespace.\n\nUse `@severity_details.adjusted.value` instead, which reflects the severity before user-defined adjustments.",
  })
  .openapi('SeverityModifierRuleAction')

