export const getApiUnstableFleetTracersRoute = createRoute({
  method: 'get',
  path: '/api/unstable/fleet/tracers',
  tags: ['Fleet Automation'],
  summary: 'List all fleet tracers',
  description:
    'Retrieve a paginated list of all fleet tracers.\n\nThis endpoint returns telemetry-derived service names from the SDK telemetry pipeline.\nThese names may differ from span-derived names in APM and are useful for querying\nservice library configurations.\nUse the `page_number` and `page_size` query parameters to paginate through results.',
  operationId: 'ListFleetTracers',
  request: {
    query: z.object({
      page_number: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(0n))
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Page number for pagination (starts at 0).',
            in: 'query',
            name: 'page_number',
            required: false,
            schema: { default: 0, format: 'int64', minimum: 0, type: 'integer' },
          },
        }),
      page_size: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(1n).max(100n))
        .default(10n)
        .exactOptional()
        .openapi({
          param: {
            description:
              'Number of results per page (must be greater than 0 and less than or equal to 100).',
            in: 'query',
            name: 'page_size',
            required: false,
            schema: { default: 10, format: 'int64', maximum: 100, minimum: 1, type: 'integer' },
          },
        }),
      sort_attribute: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Attribute to sort by.',
            in: 'query',
            name: 'sort_attribute',
            required: false,
            schema: { type: 'string' },
          },
        }),
      sort_descending: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            description: 'Sort order (true for descending, false for ascending).',
            in: 'query',
            name: 'sort_descending',
            required: false,
            schema: { default: true, type: 'boolean' },
          },
        }),
      filter: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter string for narrowing down tracer results.',
            example: 'hostname:my-host OR env:prod',
            in: 'query',
            name: 'filter',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: FleetTracersResponseSchema,
          examples: {
            default: {
              value: {
                data: {
                  attributes: {
                    tracers: [
                      {
                        env: 'production',
                        hostname: 'my-hostname',
                        language: 'java',
                        service: 'test-service',
                        tracer_version: '1.32.0',
                      },
                    ],
                  },
                  id: 'done',
                  type: 'status',
                },
                meta: { total_filtered_count: 1 },
              },
            },
          },
        },
      },
    },
    400: BadRequestResponseResponse,
    401: UnauthorizedResponseResponse,
    403: ForbiddenResponseResponse,
    404: NotFoundResponseResponse,
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: [] }],
})

