export const getApiV2ActionsExecutionPoliciesRoute = createRoute({
  method: 'get',
  path: '/api/v2/actions/execution-policies',
  tags: ['Execution Policy'],
  summary: 'List execution policies',
  description: 'Retrieve a list of execution policies for the current organization.',
  operationId: 'ListExecutionPolicies',
  request: {
    query: z.object({
      'page[size]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().max(100),
        )
        .default(100)
        .exactOptional()
        .openapi({
          param: {
            description: 'The number of execution policies to return per page.',
            example: 100,
            in: 'query',
            name: 'page[size]',
            required: false,
            schema: { default: 100, format: 'int32', maximum: 100, type: 'integer' },
          },
        }),
      'page[number]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(0).max(1000),
        )
        .default(0)
        .exactOptional()
        .openapi({
          param: {
            description: 'The page number to return.',
            example: 0,
            in: 'query',
            name: 'page[number]',
            required: false,
            schema: { default: 0, format: 'int32', maximum: 1000, minimum: 0, type: 'integer' },
          },
        }),
      'filter[name]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter execution policies by name.',
            example: 'Block prod restarts',
            in: 'query',
            name: 'filter[name]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[ids]': z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter execution policies by a list of IDs.',
            example: ['3fa85f64-5717-4562-b3fc-2c963f66afa6'],
            explode: true,
            in: 'query',
            name: 'filter[ids]',
            required: false,
            schema: { items: { type: 'string' }, type: 'array' },
            style: 'form',
          },
        }),
      'filter[integration]': z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(ExecutionPolicyIntegrationSchema),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter execution policies by a list of integrations.',
            example: ['INTEGRATION_SCRIPT'],
            explode: true,
            in: 'query',
            name: 'filter[integration]',
            required: false,
            schema: {
              items: { $ref: '#/components/schemas/ExecutionPolicyIntegration' },
              type: 'array',
            },
            style: 'form',
          },
        }),
      'filter[effects]': z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(ExecutionPolicyEffectSchema),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter execution policies by a list of effects.',
            example: ['allow'],
            explode: true,
            in: 'query',
            name: 'filter[effects]',
            required: false,
            schema: {
              items: { $ref: '#/components/schemas/ExecutionPolicyEffect' },
              type: 'array',
            },
            style: 'form',
          },
        }),
      'filter[creator_ids]': z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter execution policies by a list of creator IDs.',
            example: ['3fa85f64-5717-4562-b3fc-2c963f66afa6'],
            explode: true,
            in: 'query',
            name: 'filter[creator_ids]',
            required: false,
            schema: { items: { type: 'string' }, type: 'array' },
            style: 'form',
          },
        }),
      sort: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'The sort order for the results. Prefix a field with `-` to sort in\ndescending order. Valid fields are `name`, `effect`, `integration`,\n`created_at`, and `updated_at`.',
            example: ['-created_at'],
            explode: true,
            in: 'query',
            name: 'sort',
            required: false,
            schema: { items: { type: 'string' }, type: 'array' },
            style: 'form',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: ExecutionPolicyListResponseSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      action_pattern: {
                        action_fqns: ['com.datadoghq.script.*'],
                        integration: 'INTEGRATION_SCRIPT',
                      },
                      created_at: '2026-01-15T10:00:00.000Z',
                      created_by: '3fa85f64-5717-4562-b3fc-2c963f66afa6',
                      effect: 'allow',
                      name: 'Block prod restarts',
                      targets: [],
                      updated_at: '2026-01-15T10:00:00.000Z',
                      updated_by: '3fa85f64-5717-4562-b3fc-2c963f66afa6',
                      version: 1,
                    },
                    id: '3fa85f64-5717-4562-b3fc-2c963f66afa6',
                    type: 'execution_policy',
                  },
                ],
                meta: { page: { total: 1 } },
              },
            },
          },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    403: {
      description: 'Forbidden',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
  },
})

