export const getApiV2ApicatalogApiRoute = createRoute({
  method: 'get',
  path: '/api/v2/apicatalog/api',
  tags: ['API Management'],
  summary: 'List APIs',
  description: 'List APIs and their IDs.',
  operationId: 'ListAPIs',
  request: {
    query: z.object({
      query: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter APIs by name',
            in: 'query',
            name: 'query',
            required: false,
            schema: { example: 'payments', type: 'string' },
          },
          example: 'payments',
        }),
      'page[limit]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(1n))
        .default(20n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Number of items per page.',
            in: 'query',
            name: 'page[limit]',
            required: false,
            schema: { default: 20, format: 'int64', minimum: 1, type: 'integer' },
          },
        }),
      'page[offset]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(0n))
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Offset for pagination.',
            in: 'query',
            name: 'page[offset]',
            required: false,
            schema: { default: 0, format: 'int64', minimum: 0, type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: ListAPIsResponseSchema,
          examples: {
            default: {
              value: {
                data: [{ attributes: { name: 'Payments API' }, id: 'abc-123' }],
                meta: { pagination: { limit: 20, offset: 0, total_count: 1 } },
              },
            },
          },
        },
      },
    },
    400: {
      description: 'Bad request',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    403: {
      description: 'Forbidden',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
  },
  deprecated: true,
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['apm_api_catalog_read'] }],
})

