export const getApiV2AppBuilderAppsRoute = createRoute({
  method: 'get',
  path: '/api/v2/app-builder/apps',
  tags: ['App Builder'],
  summary: 'List Apps',
  description:
    'List all apps, with optional filters and sorting. This endpoint is paginated. Only basic app information such as the app ID, name, and description is returned by this endpoint. This API requires a [registered application key](https://docs.datadoghq.com/api/latest/action-connection/#register-a-new-app-key). Alternatively, you can configure these permissions [in the UI](https://docs.datadoghq.com/account_management/api-app-keys/#actions-api-access).',
  operationId: 'ListApps',
  request: {
    query: z.object({
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description: 'The number of apps to return per page.',
            in: 'query',
            name: 'limit',
            required: false,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
      page: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description: 'The page number to return.',
            in: 'query',
            name: 'page',
            required: false,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
      'filter[user_name]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: "Filter apps by the app creator. Usually the user's email.",
            in: 'query',
            name: 'filter[user_name]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[user_uuid]': z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            description: "Filter apps by the app creator's UUID.",
            example: '65bb1f25-52e1-4510-9f8d-22d1516ed693',
            in: 'query',
            name: 'filter[user_uuid]',
            required: false,
            schema: { format: 'uuid', type: 'string' },
          },
        }),
      'filter[name]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by app name.',
            in: 'query',
            name: 'filter[name]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[query]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter apps by the app name or the app creator.',
            in: 'query',
            name: 'filter[query]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[deployed]': z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter apps by whether they are published.',
            in: 'query',
            name: 'filter[deployed]',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
      'filter[tags]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter apps by tags.',
            in: 'query',
            name: 'filter[tags]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[favorite]': z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter apps by whether you have added them to your favorites.',
            in: 'query',
            name: 'filter[favorite]',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
      'filter[self_service]': z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter apps by whether they are enabled for self-service.',
            in: 'query',
            name: 'filter[self_service]',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
      sort: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(AppsSortFieldSchema),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'The fields and direction to sort apps by.',
            explode: false,
            in: 'query',
            name: 'sort',
            required: false,
            schema: { items: { $ref: '#/components/schemas/AppsSortField' }, type: 'array' },
            style: 'form',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: ListAppsResponseSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      description: 'A sample app',
                      favorite: false,
                      name: 'My App',
                      selfService: false,
                      tags: ['team:webshop'],
                    },
                    id: '00000000-0000-0000-0000-000000000001',
                    type: 'appDefinitions',
                  },
                ],
                meta: { page: { totalCount: 1, totalFilteredCount: 1 } },
              },
            },
          },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    403: {
      description: 'Forbidden',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
  },
})

