export const getApiV2BitsAiInvestigationsRoute = createRoute({
  method: 'get',
  path: '/api/v2/bits-ai/investigations',
  tags: ['Bits AI'],
  summary: 'List Bits AI investigations',
  description: 'List all Bits AI investigations for the organization.',
  operationId: 'ListInvestigations',
  request: {
    query: z.object({
      'page[offset]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description: 'Offset for pagination.',
            example: 0,
            in: 'query',
            name: 'page[offset]',
            required: false,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
      'page[limit]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().max(100n))
        .default(25n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Maximum number of investigations to return.',
            example: 25,
            in: 'query',
            name: 'page[limit]',
            required: false,
            schema: { default: 25, format: 'int64', maximum: 100, type: 'integer' },
          },
        }),
      'filter[monitor_id]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter investigations by monitor ID.',
            example: 12345678,
            in: 'query',
            name: 'filter[monitor_id]',
            required: false,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: ListInvestigationsResponseSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      status: 'conclusive',
                      title: 'Monitor alert investigation for web-server-01',
                    },
                    id: 'a1b2c3d4-5e6f-7a8b-9c0d-1e2f3a4b5c6d',
                    type: 'investigation',
                  },
                ],
                links: {
                  first:
                    'https://api.datadoghq.com/api/v2/bits-ai/investigations?page[offset]=0&page[limit]=10',
                  next: 'https://api.datadoghq.com/api/v2/bits-ai/investigations?page[offset]=10&page[limit]=10',
                  self: 'https://api.datadoghq.com/api/v2/bits-ai/investigations?page[offset]=0&page[limit]=10',
                },
                meta: { page: { limit: 10, offset: 0, total: 50 } },
              },
            },
          },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['bits_investigations_read'] }],
})

