export const getApiV2CasesCaseIdTimelinesRoute = createRoute({
  method: 'get',
  path: '/api/v2/cases/{case_id}/timelines',
  tags: ['Case Management'],
  summary: 'Get case timeline',
  description:
    'Returns the timeline of events for a work item, including comments, status changes, and other activity. Supports pagination and sort order.',
  operationId: 'ListCaseTimeline',
  request: {
    params: z.object({ case_id: CaseIDPathParameterParamsSchema }),
    query: z.object({
      'page[size]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(100n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Number of timeline cells to return per page.',
            in: 'query',
            name: 'page[size]',
            required: false,
            schema: { default: 100, format: 'int64', type: 'integer' },
          },
        }),
      'page[number]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Zero-based page number for pagination.',
            in: 'query',
            name: 'page[number]',
            required: false,
            schema: { default: 0, format: 'int64', type: 'integer' },
          },
        }),
      'sort[ascending]': z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description:
              'If `true`, returns timeline cells in chronological order (oldest first). Defaults to `false` (newest first).',
            in: 'query',
            name: 'sort[ascending]',
            required: false,
            schema: { default: false, type: 'boolean' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: TimelineResponseSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      cell_content: { message: 'This is a comment' },
                      created_at: '2024-01-01T00:00:00+00:00',
                      type: 'COMMENT',
                    },
                    id: '00000000-0000-0000-0000-000000000001',
                    type: 'timeline_cell',
                  },
                ],
              },
            },
          },
        },
      },
    },
    400: BadRequestResponseResponse,
    401: UnauthorizedResponseResponse,
    403: ForbiddenResponseResponse,
    404: NotFoundResponseResponse,
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['cases_read'] }],
})

