export const postApiV2CiPipelinesAnalyticsAggregateRoute = createRoute({
  method: 'post',
  path: '/api/v2/ci/pipelines/analytics/aggregate',
  tags: ['CI Visibility Pipelines'],
  summary: 'Aggregate pipelines events',
  description:
    'Use this API endpoint to aggregate CI Visibility pipeline events into buckets of computed metrics and timeseries.',
  operationId: 'AggregateCIAppPipelineEvents',
  request: {
    body: {
      content: {
        'application/json': {
          schema: CIAppPipelinesAggregateRequestSchema,
          examples: {
            default: {
              value: {
                compute: [
                  { aggregation: 'pc90', interval: '5m', metric: '@duration', type: 'timeseries' },
                ],
                filter: {
                  from: 'now-15m',
                  query: '@ci.provider.name:github AND @ci.status:error',
                  to: 'now',
                },
                group_by: [
                  {
                    facet: '@ci.status',
                    histogram: { interval: 10, max: 100, min: 50 },
                    sort: { aggregation: 'count', order: 'asc' },
                  },
                ],
                options: { timezone: 'GMT' },
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: CIAppPipelinesAnalyticsAggregateResponseSchema,
          examples: {
            default: {
              value: {
                data: {
                  buckets: [
                    {
                      by: { '@ci.status': 'error' },
                      computes: { pc90: [{ time: '2020-06-08T11:55:00.123Z', value: 2345 }] },
                    },
                  ],
                },
              },
            },
          },
        },
      },
    },
    400: BadRequestResponseResponse,
    403: NotAuthorizedResponseResponse,
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['ci_visibility_read'] }],
})

export const getApiV2CiPipelinesEventsRoute = createRoute({
  method: 'get',
  path: '/api/v2/ci/pipelines/events',
  tags: ['CI Visibility Pipelines'],
  summary: 'Get a list of pipelines events',
  description:
    'List endpoint returns CI Visibility pipeline events that match a [search query](https://docs.datadoghq.com/continuous_integration/explorer/search_syntax/).\n[Results are paginated similarly to logs](https://docs.datadoghq.com/logs/guide/collect-multiple-logs-with-pagination).\n\nUse this endpoint to see your latest pipeline events.',
  operationId: 'ListCIAppPipelineEvents',
  request: {
    query: z.object({
      'filter[query]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Search query following log syntax.',
            example: '@ci.provider.name:github @ci.pipeline.name:Pull Request Labeler',
            in: 'query',
            name: 'filter[query]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[from]': z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            description: 'Minimum timestamp for requested events.',
            example: '2019-01-02T09:42:36.320Z',
            in: 'query',
            name: 'filter[from]',
            required: false,
            schema: { format: 'date-time', type: 'string' },
          },
        }),
      'filter[to]': z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            description: 'Maximum timestamp for requested events.',
            example: '2019-01-03T09:42:36.320Z',
            in: 'query',
            name: 'filter[to]',
            required: false,
            schema: { format: 'date-time', type: 'string' },
          },
        }),
      sort: CIAppSortSchema.openapi({
        param: {
          description: 'Order of events in results.',
          in: 'query',
          name: 'sort',
          required: false,
          schema: { $ref: '#/components/schemas/CIAppSort' },
        },
      }).exactOptional(),
      'page[cursor]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'List following results with a cursor provided in the previous query.',
            example:
              'eyJzdGFydEF0IjoiQVFBQUFYS2tMS3pPbm40NGV3QUFBQUJCV0V0clRFdDZVbG8zY3pCRmNsbHJiVmxDWlEifQ==',
            in: 'query',
            name: 'page[cursor]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'page[limit]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().max(1000),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            description: 'Maximum number of events in the response.',
            example: 25,
            in: 'query',
            name: 'page[limit]',
            required: false,
            schema: { default: 10, format: 'int32', maximum: 1000, type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: CIAppPipelineEventsResponseSchema,
          examples: { default: { value: { data: [], meta: { page: {} } } } },
        },
      },
    },
    400: BadRequestResponseResponse,
    403: NotAuthorizedResponseResponse,
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['ci_visibility_read'] }],
})

