export const getApiV2ContainerImagesRoute = createRoute({
  method: 'get',
  path: '/api/v2/container_images',
  tags: ['Container Images'],
  summary: 'Get all Container Images',
  description:
    'Get all Container Images for your organization.\n**Note**: To enrich the data returned by this endpoint with security scans, see the new [api/v2/security/scanned-assets-metadata](https://docs.datadoghq.com/api/latest/security-monitoring/#list-scanned-assets-metadata) endpoint.',
  operationId: 'ListContainerImages',
  request: {
    query: z.object({
      'filter[tags]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Comma-separated list of tags to filter Container Images by.',
            example: 'short_image:redis,status:running',
            in: 'query',
            name: 'filter[tags]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      group_by: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Comma-separated list of tags to group Container Images by.',
            example: 'registry,image_tags',
            in: 'query',
            name: 'group_by',
            required: false,
            schema: { type: 'string' },
          },
        }),
      sort: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Attribute to sort Container Images by.',
            example: 'container_count',
            in: 'query',
            name: 'sort',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'page[size]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1).max(10000),
        )
        .default(1000)
        .exactOptional()
        .openapi({
          param: {
            description: 'Maximum number of results returned.',
            in: 'query',
            name: 'page[size]',
            required: false,
            schema: { default: 1000, format: 'int32', maximum: 10000, minimum: 1, type: 'integer' },
          },
        }),
      'page[cursor]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'String to query the next page of results.\nThis key is provided with each valid response from the API in `meta.pagination.next_cursor`.',
            in: 'query',
            name: 'page[cursor]',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: ContainerImagesResponseSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      container_count: 1,
                      image_tags: ['latest'],
                      name: 'nginx',
                      registry: 'docker.io',
                      repository: 'library/nginx',
                      short_image: 'nginx',
                    },
                    id: 'abc-123',
                    type: 'container_image',
                  },
                ],
                meta: { pagination: { limit: 1000, total: 1, type: 'cursor_limit' } },
              },
            },
          },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
    403: {
      description: 'Authentication Error',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: [] }],
})

