export const postApiV2CostArbitraryRuleRoute = createRoute({
  method: 'post',
  path: '/api/v2/cost/arbitrary_rule',
  tags: ['Cloud Cost Management'],
  summary: 'Create custom allocation rule',
  description:
    'Create a new custom allocation rule with the specified filters and allocation strategy.\n\n**Strategy Methods:**\n- **PROPORTIONAL/EVEN**: Allocates costs proportionally/evenly based on existing costs. Requires: granularity, allocated_by_tag_keys. Optional: based_on_costs, allocated_by_filters, evaluate_grouped_by_tag_keys, evaluate_grouped_by_filters.\n- **PROPORTIONAL_TIMESERIES/EVEN_TIMESERIES**: Allocates based on timeseries data. Requires: granularity, based_on_timeseries. Optional: evaluate_grouped_by_tag_keys.\n- **PERCENT**: Allocates fixed percentages to specific tags. Requires: allocated_by (array of percentage allocations).\n\n**Filter Conditions:**\n- Use **value** for single-value conditions: "is", "is not", "contains", "=", "!=", "like", "not like"\n- Use **values** for multi-value conditions: "in", "not in"\n- Cannot use both value and values simultaneously.\n\n**Supported operators**: is, is not, contains, in, not in, =, !=, like, not like',
  operationId: 'CreateCustomAllocationRule',
  request: {
    body: {
      content: {
        'application/json': {
          schema: ArbitraryCostUpsertRequestSchema,
          examples: {
            default: {
              value: {
                data: {
                  attributes: {
                    costs_to_allocate: [
                      { condition: 'is', tag: 'account_id', value: '123456789' },
                      {
                        condition: 'in',
                        tag: 'environment',
                        value: '',
                        values: ['production', 'staging'],
                      },
                    ],
                    enabled: true,
                    order_id: 1,
                    provider: ['aws', 'gcp'],
                    rule_name: 'example-arbitrary-cost-rule',
                    strategy: {
                      allocated_by_tag_keys: ['team', 'environment'],
                      based_on_costs: [
                        { condition: 'is', tag: 'service', value: 'web-api' },
                        {
                          condition: 'not in',
                          tag: 'team',
                          value: '',
                          values: ['legacy', 'deprecated'],
                        },
                      ],
                      granularity: 'daily',
                      method: 'proportional',
                    },
                    type: 'shared',
                  },
                  type: 'upsert_arbitrary_rule',
                },
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: ArbitraryRuleResponseSchema,
          examples: {
            default: {
              value: {
                data: {
                  attributes: {
                    costs_to_allocate: [{ condition: 'is', tag: 'account_id', value: '123456789' }],
                    created: '2024-01-01T00:00:00+00:00',
                    enabled: true,
                    order_id: 1,
                    provider: ['aws'],
                    rule_name: 'example-arbitrary-cost-rule',
                    strategy: {
                      allocated_by_tag_keys: ['team'],
                      granularity: 'daily',
                      method: 'proportional',
                    },
                    type: 'shared',
                    updated: '2024-01-01T00:00:00+00:00',
                    version: 1,
                  },
                  id: '123',
                  type: 'arbitrary_rule',
                },
              },
            },
          },
        },
      },
    },
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['cloud_cost_management_write'] }],
})

export const postApiV2CostArbitraryRuleReorderRoute = createRoute({
  method: 'post',
  path: '/api/v2/cost/arbitrary_rule/reorder',
  tags: ['Cloud Cost Management'],
  summary: 'Reorder custom allocation rules',
  description:
    'Reorder custom allocation rules - Change the execution order of custom allocation rules.\n\n**Important**: You must provide the **complete list** of all rule IDs in the desired execution order. The API will reorder ALL rules according to the provided sequence.\n\nRules are executed in the order specified, with lower indices (earlier in the array) having higher priority.\n\n**Example**: If you have rules with IDs [123, 456, 789] and want to change order from 123→456→789 to 456→123→789, send: [{"id": "456"}, {"id": "123"}, {"id": "789"}]',
  operationId: 'ReorderCustomAllocationRules',
  request: {
    body: {
      content: {
        'application/json': {
          schema: ReorderRuleResourceArraySchema,
          examples: {
            default: {
              value: {
                data: [
                  { id: '456', type: 'arbitrary_rule' },
                  { id: '123', type: 'arbitrary_rule' },
                  { id: '789', type: 'arbitrary_rule' },
                ],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    204: { description: 'Successfully reordered rules' },
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['cloud_cost_management_write'] }],
})

