export const patchApiV2CostArbitraryRuleRuleIdRoute = createRoute({
  method: 'patch',
  path: '/api/v2/cost/arbitrary_rule/{rule_id}',
  tags: ['Cloud Cost Management'],
  summary: 'Update custom allocation rule',
  description:
    'Update an existing custom allocation rule with new filters and allocation strategy.\n\n**Strategy Methods:**\n- **PROPORTIONAL/EVEN**: Allocates costs proportionally/evenly based on existing costs. Requires: granularity, allocated_by_tag_keys. Optional: based_on_costs, allocated_by_filters, evaluate_grouped_by_tag_keys, evaluate_grouped_by_filters.\n- **PROPORTIONAL_TIMESERIES/EVEN_TIMESERIES**: Allocates based on timeseries data. Requires: granularity, based_on_timeseries. Optional: evaluate_grouped_by_tag_keys.\n- **PERCENT**: Allocates fixed percentages to specific tags. Requires: allocated_by (array of percentage allocations).\n- **USAGE_METRIC**: Allocates based on usage metrics (implementation varies).\n\n**Filter Conditions:**\n- Use **value** for single-value conditions: "is", "is not", "contains", "=", "!=", "like", "not like"\n- Use **values** for multi-value conditions: "in", "not in"\n- Cannot use both value and values simultaneously.\n\n**Supported operators**: is, is not, contains, in, not in, =, !=, like, not like',
  operationId: 'UpdateCustomAllocationRule',
  request: {
    params: z.object({
      rule_id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description: 'The unique identifier of the custom allocation rule',
            in: 'path',
            name: 'rule_id',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: ArbitraryCostUpsertRequestSchema,
          examples: {
            default: {
              value: {
                data: {
                  attributes: {
                    costs_to_allocate: [
                      { condition: 'is', tag: 'account_id', value: '123456789' },
                      {
                        condition: 'in',
                        tag: 'environment',
                        value: '',
                        values: ['production', 'staging'],
                      },
                    ],
                    enabled: true,
                    order_id: 1,
                    provider: ['aws', 'gcp'],
                    rule_name: 'example-arbitrary-cost-rule',
                    strategy: {
                      allocated_by_tag_keys: ['team', 'environment'],
                      based_on_costs: [
                        { condition: 'is', tag: 'service', value: 'web-api' },
                        {
                          condition: 'not in',
                          tag: 'team',
                          value: '',
                          values: ['legacy', 'deprecated'],
                        },
                      ],
                      granularity: 'daily',
                      method: 'proportional',
                    },
                    type: 'shared',
                  },
                  type: 'upsert_arbitrary_rule',
                },
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: ArbitraryRuleResponseSchema,
          examples: {
            default: {
              value: {
                data: {
                  attributes: {
                    costs_to_allocate: [{ condition: 'is', tag: 'account_id', value: '123456789' }],
                    created: '2024-01-01T00:00:00+00:00',
                    enabled: true,
                    order_id: 1,
                    provider: ['aws'],
                    rule_name: 'example-arbitrary-cost-rule',
                    strategy: {
                      allocated_by_tag_keys: ['team'],
                      granularity: 'daily',
                      method: 'proportional',
                    },
                    type: 'shared',
                    updated: '2024-01-01T00:00:00+00:00',
                    version: 1,
                  },
                  id: '123',
                  type: 'arbitrary_rule',
                },
              },
            },
          },
        },
      },
    },
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['cloud_cost_management_write'] }],
})

