export const getApiV2CostBudgetBudgetIdRoute = createRoute({
  method: 'get',
  path: '/api/v2/cost/budget/{budget_id}',
  tags: ['Cloud Cost Management'],
  summary: 'Get budget',
  description:
    'Get a budget by ID. Pass `actual=true` or `forecast=true` to include cost data in the response. Use `start` and `end` (millisecond epochs, both required) to set the cost window. When `forecast=true`, each entry also includes `ootb_forecast` (the ML forecast before overrides) and `custom_forecast` (`null` if no override is set, a number if one is).',
  operationId: 'GetBudget',
  request: {
    params: z.object({ budget_id: BudgetIDParamsSchema }),
    query: z.object({
      actual: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description: 'When `true`, includes actual cost data in the response.',
            in: 'query',
            name: 'actual',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
      forecast: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description:
              'When `true`, includes forecast cost data in the response, including `ootb_forecast` and `custom_forecast` per entry.',
            in: 'query',
            name: 'forecast',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
      start: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description:
              'Start of the cost window in milliseconds since epoch. Must be used together with `end`.',
            in: 'query',
            name: 'start',
            required: false,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
      end: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description:
              'End of the cost window in milliseconds since epoch. Must be used together with `start`.',
            in: 'query',
            name: 'end',
            required: false,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: BudgetWithEntriesSchema,
          examples: {
            default: {
              value: {
                data: {
                  attributes: {
                    costs: {
                      actual: 850.25,
                      amount: 1000,
                      forecast: 1100.5,
                      ootb_forecast: 1100.5,
                    },
                    costs_period_end: 1740873600000,
                    costs_period_start: 1738281600000,
                    costs_unit: {
                      family: 'currency',
                      id: 42,
                      name: 'dollar',
                      plural: 'dollars',
                      scale_factor: 1,
                      short_name: '$',
                    },
                    created_at: 1738258683590,
                    created_by: '00000000-0a0a-0a0a-aaa0-00000000000a',
                    end_month: 202502,
                    entries: [
                      {
                        amount: 500,
                        costs: {
                          actual: 425.5,
                          amount: 500,
                          custom_forecast: null,
                          forecast: 550.25,
                          ootb_forecast: 550.25,
                        },
                        month: 202501,
                        tag_filters: [{ tag_key: 'service', tag_value: 'ec2' }],
                      },
                    ],
                    metrics_query: 'aws.cost.amortized{service:ec2} by {service}',
                    name: 'my budget',
                    org_id: 123,
                    start_month: 202501,
                    total_amount: 1000,
                    updated_at: 1738258683590,
                    updated_by: '00000000-0a0a-0a0a-aaa0-00000000000a',
                  },
                  id: '00000000-0a0a-0a0a-aaa0-00000000000a',
                  type: 'budget',
                },
              },
            },
          },
        },
      },
    },
    400: BadRequestResponseResponse,
    404: NotFoundResponseResponse,
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: [] }],
})

