export const getApiV2CostTagKeysTagKeyRoute = createRoute({
  method: 'get',
  path: '/api/v2/cost/tag_keys/{tag_key}',
  tags: ['Cloud Cost Management'],
  summary: 'Get a Cloud Cost Management tag key',
  description:
    'Get details for a specific Cloud Cost Management tag key, including example tag values and description.',
  operationId: 'GetCostTagKey',
  request: {
    params: z.object({ tag_key: TagKeyParamsSchema }),
    query: z.object({
      'filter[metric]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'The Cloud Cost Management metric to scope the tag key details to. When omitted, returns details across all metrics.',
            in: 'query',
            name: 'filter[metric]',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'page[size]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().max(10000),
        )
        .default(50)
        .exactOptional()
        .openapi({
          param: {
            description:
              'Controls the size of the internal tag value search scope. This does **not** restrict the number of example tag values returned in the response. Defaults to 50, maximum 10000.',
            in: 'query',
            name: 'page[size]',
            schema: { default: 50, format: 'int32', maximum: 10000, type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: CostTagKeyResponseSchema,
          examples: {
            default: {
              value: {
                data: {
                  attributes: {
                    details: {
                      description: 'The cloud provider name reported for the cost line item.',
                      tag_values: ['aws', 'gcp', 'azure'],
                    },
                    sources: ['focus'],
                    value: 'providername',
                  },
                  id: 'providername',
                  type: 'cost_tag_key',
                },
              },
            },
          },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    403: {
      description: 'Forbidden',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    404: {
      description: 'Not Found',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['cloud_cost_management_read'] }],
})

