export const getApiV2CostTagsRoute = createRoute({
  method: 'get',
  path: '/api/v2/cost/tags',
  tags: ['Cloud Cost Management'],
  summary: 'List Cloud Cost Management tags',
  description: 'List Cloud Cost Management tags for a given metric.',
  operationId: 'ListCostTags',
  request: {
    query: z.object({
      'filter[metric]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'The Cloud Cost Management metric to scope the tags to. When omitted, returns tags across all metrics.',
            in: 'query',
            name: 'filter[metric]',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'filter[match]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'A substring used to filter the returned tags by name.',
            in: 'query',
            name: 'filter[match]',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'filter[tags]': z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter to return only tags that appear with the given `key:value` tag values. For example, `filter[tags]=providername:aws` returns tags found on the same cost data, such as `aws_instance_type:t3.micro` and `aws_instance_type:m5.large`.',
            in: 'query',
            name: 'filter[tags]',
            schema: { items: { type: 'string' }, type: 'array' },
            required: false,
          },
        }),
      'filter[tag_keys]': z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'Restrict the returned tags to those whose key matches one of the given tag keys.',
            in: 'query',
            name: 'filter[tag_keys]',
            schema: { items: { type: 'string' }, type: 'array' },
            required: false,
          },
        }),
      'page[size]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().max(10000),
        )
        .default(50)
        .exactOptional()
        .openapi({
          param: {
            description:
              'Controls the size of the internal tag search scope. This does **not** restrict the number of tags returned in the response. Defaults to 50, maximum 10000.',
            in: 'query',
            name: 'page[size]',
            schema: { default: 50, format: 'int32', maximum: 10000, type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: CostTagsResponseSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: { sources: ['focus'], value: 'providername:aws' },
                    id: 'providername:aws',
                    type: 'cost_tag',
                  },
                  {
                    attributes: { sources: ['focus'], value: 'providername:gcp' },
                    id: 'providername:gcp',
                    type: 'cost_tag',
                  },
                ],
              },
            },
          },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    403: {
      description: 'Forbidden',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['cloud_cost_management_read'] }],
})

