export const getApiV2DashboardListsManualDashboardListIdDashboardsRoute = createRoute({
  method: 'get',
  path: '/api/v2/dashboard/lists/manual/{dashboard_list_id}/dashboards',
  tags: ['Dashboard Lists'],
  summary: 'Get items of a Dashboard List',
  description: 'Fetch the dashboard list’s dashboard definitions.',
  operationId: 'GetDashboardListItems',
  request: {
    params: z.object({
      dashboard_list_id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description: 'ID of the dashboard list to get items from.',
            in: 'path',
            name: 'dashboard_list_id',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: DashboardListItemsSchema,
          examples: {
            default: {
              value: { dashboards: [{ id: 'q5j-nti-fv6', type: 'host_timeboard' }], total: 1 },
            },
          },
        },
      },
    },
    403: {
      description: 'Forbidden',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
    404: {
      description: 'Not Found',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['dashboards_read'] }],
})

