export const getApiV2DashboardsUsageRoute = createRoute({
  method: 'get',
  path: '/api/v2/dashboards/usage',
  tags: ['Dashboards'],
  summary: 'Get usage stats for all dashboards',
  description:
    "Get paginated usage statistics for every dashboard in the caller's organization. Use `page[limit]` and `page[offset]` to walk the result set. Use `filter[edited_before]` or `filter[viewed_before]` to narrow results by edit or view date. View-count fields depend on Real User Monitoring (RUM) and are `null` or `0` in orgs without RUM. **View counts are refreshed once per day** and **only reflect views recorded starting January 2025**; views prior to that date are not included.",
  operationId: 'ListDashboardsUsage',
  request: {
    query: z.object({
      'page[limit]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(250n)
        .exactOptional()
        .openapi({
          param: {
            description:
              'Maximum number of dashboards to return per page. Server-side maximum is 500; values above 500 return a 400 Bad Request.',
            in: 'query',
            name: 'page[limit]',
            required: false,
            schema: { default: 250, format: 'int64', type: 'integer' },
          },
        }),
      'page[offset]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(0n))
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Zero-based offset into the result set.',
            in: 'query',
            name: 'page[offset]',
            required: false,
            schema: { default: 0, format: 'int64', minimum: 0, type: 'integer' },
          },
        }),
      'filter[edited_before]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Return only dashboards whose last edit (`edited_at`) is strictly before this ISO 8601 timestamp (`edited_at < value`; boundary matches are excluded). Must include a timezone offset (for example, `Z` or `+00:00`); naive timestamps return HTTP 400.',
            in: 'query',
            name: 'filter[edited_before]',
            required: false,
            schema: { example: '2025-04-26T00:00:00Z', type: 'string' },
          },
          example: '2025-04-26T00:00:00Z',
        }),
      'filter[viewed_before]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Return only dashboards whose most recent view (`viewed_at`) is strictly before this ISO 8601 timestamp, including dashboards that have never been viewed. Must include a timezone offset; naive timestamps return HTTP 400. Orgs without Real User Monitoring (RUM) will see all dashboards returned by this filter.',
            in: 'query',
            name: 'filter[viewed_before]',
            required: false,
            schema: { example: '2025-04-26T00:00:00Z', type: 'string' },
          },
          example: '2025-04-26T00:00:00Z',
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: ListDashboardsUsageResponseSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      author: {
                        handle: 'jane.doe@example.com',
                        id: '00000000-0000-0000-0000-000000000000',
                        is_disabled: false,
                        name: 'Jane Doe',
                      },
                      created_at: '2026-01-15T09:30:00.000Z',
                      dashboard_quality_score: 0.85,
                      edited_at: '2026-04-20T11:05:00.000Z',
                      org_id: 100,
                      teams: ['sre'],
                      title: 'My production overview',
                      total_views: 42,
                      total_views_by_type: { embed: 12, in_app: 30 },
                      viewed_at: '2026-05-01T14:22:10.000Z',
                      viewer: {
                        handle: 'john.smith@example.com',
                        id: '00000000-0000-0000-0000-000000000001',
                        is_disabled: false,
                        name: 'John Smith',
                      },
                      widget_count: 12,
                      widget_count_by_type: { query_value: 4, timeseries: 8 },
                    },
                    id: 'q5j-nti-fv6',
                    type: 'dashboards-usages',
                  },
                ],
                links: {
                  first:
                    'https://api.datadoghq.com/api/v2/dashboards/usage?page[offset]=0&page[limit]=250',
                  last: 'https://api.datadoghq.com/api/v2/dashboards/usage?page[offset]=1000&page[limit]=250',
                  next: 'https://api.datadoghq.com/api/v2/dashboards/usage?page[offset]=250&page[limit]=250',
                  self: 'https://api.datadoghq.com/api/v2/dashboards/usage',
                },
                meta: {
                  page: {
                    first_offset: 0,
                    last_offset: 1000,
                    limit: 250,
                    next_offset: 250,
                    offset: 0,
                    prev_offset: null,
                    total: 1234,
                    type: 'offset_limit',
                  },
                },
              },
            },
          },
        },
      },
    },
    400: BadRequestResponseResponse,
    403: ForbiddenResponseResponse,
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['dashboards_read'] }],
})

