export const getApiV2DeletionRequestsRoute = createRoute({
  method: 'get',
  path: '/api/v2/deletion/requests',
  tags: ['Data Deletion'],
  summary: 'Gets a list of data deletion requests',
  description: 'Gets a list of data deletion requests based on several filter parameters.',
  operationId: 'GetDataDeletionRequests',
  request: {
    query: z.object({
      next_page: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'The next page of the previous search. If the next_page parameter is included, the rest of the query elements are ignored.',
            example: 'cGFnZTI=',
            in: 'query',
            name: 'next_page',
            required: false,
            schema: { type: 'string' },
          },
        }),
      product: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Retrieve only the requests related to the given product.',
            example: 'logs',
            in: 'query',
            name: 'product',
            required: false,
            schema: { type: 'string' },
          },
        }),
      query: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Retrieve only the requests that matches the given query.',
            example: 'service:xyz host:abc',
            in: 'query',
            name: 'query',
            required: false,
            schema: { type: 'string' },
          },
        }),
      status: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Retrieve only the requests with the given status.',
            example: 'pending',
            in: 'query',
            name: 'status',
            required: false,
            schema: { type: 'string' },
          },
        }),
      page_size: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(1n).max(50n))
        .default(50n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Sets the page size of the search.',
            example: '50',
            in: 'query',
            name: 'page_size',
            required: false,
            schema: { default: 50, format: 'int64', maximum: 50, minimum: 1, type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: GetDataDeletionsResponseBodySchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      created_at: '2024-01-01T00:00:00.000000Z',
                      created_by: 'test@example.com',
                      displayed_total: 100,
                      from_time: 1672527600000,
                      is_created: true,
                      org_id: 123,
                      product: 'logs',
                      query: 'service:xyz host:abc',
                      source: 'standard',
                      starting_at: '2024-01-01T02:00:00.000000Z',
                      status: 'pending',
                      to_time: 1704063600000,
                      total_unrestricted: 100,
                      updated_at: '2024-01-01T00:00:00.000000Z',
                    },
                    id: '1',
                    type: 'deletion_request',
                  },
                ],
                meta: { next_page: 'cGFnZTI=', product: 'logs' },
              },
            },
          },
        },
      },
    },
    400: BadRequestResponseResponse,
    403: ForbiddenResponseResponse,
    429: TooManyRequestsResponseResponse,
    500: {
      description: 'Internal server error',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: [] }],
})

