export const postApiV2DeploymentsGatesEvaluationRoute = createRoute({
  method: 'post',
  path: '/api/v2/deployments/gates/evaluation',
  tags: ['Deployment Gates'],
  summary: 'Trigger a deployment gate evaluation',
  description:
    'Triggers an asynchronous deployment gate evaluation for the given service and environment.\nReturns an evaluation ID that can be used to poll for the result via the\n`GET /api/v2/deployments/gates/evaluation/{id}` endpoint.\n\nWhen the `configuration` attribute is provided, rules are evaluated inline from that configuration\nand no pre-configured gate is required. When `configuration` is omitted, rules are resolved from the\ngate pre-configured for the given service and environment through the Datadog UI, API, or Terraform.',
  operationId: 'TriggerDeploymentGatesEvaluation',
  request: {
    body: {
      content: {
        'application/json': {
          schema: DeploymentGatesEvaluationRequestSchema,
          examples: {
            default: {
              summary: 'Evaluate a preconfigured gate',
              value: {
                data: {
                  attributes: {
                    env: 'staging',
                    identifier: 'pre-deploy',
                    primary_tag: 'region:us-east-1',
                    service: 'transaction-backend',
                    version: 'v1.2.3',
                  },
                  type: 'deployment_gates_evaluation_request',
                },
              },
            },
            'with-configuration': {
              summary: 'Evaluate with inline rule configuration',
              value: {
                data: {
                  attributes: {
                    configuration: {
                      dry_run: false,
                      rules: [
                        {
                          dry_run: false,
                          name: 'error rate monitors',
                          options: {
                            duration: 300,
                            query: 'service:transaction-backend env:production',
                          },
                          type: 'monitor',
                        },
                        {
                          dry_run: false,
                          name: 'apm faulty deployment',
                          options: { duration: 900, excluded_resources: ['GET /healthcheck'] },
                          type: 'faulty_deployment_detection',
                        },
                      ],
                    },
                    env: 'production',
                    service: 'transaction-backend',
                    version: '1.2.3',
                  },
                  type: 'deployment_gates_evaluation_request',
                },
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    202: {
      description: 'Accepted',
      content: {
        'application/json': {
          schema: DeploymentGatesEvaluationResponseSchema,
          examples: {
            default: {
              value: {
                data: {
                  attributes: { evaluation_id: '00000000-0000-0000-0000-000000000001' },
                  id: '00000000-0000-0000-0000-000000000001',
                  type: 'deployment_gates_evaluation_response',
                },
              },
            },
          },
        },
      },
    },
    400: HTTPCDGatesBadRequestResponseResponse,
    401: UnauthorizedResponseResponse,
    403: ForbiddenResponseResponse,
    404: HTTPCDGatesNotFoundResponseResponse,
    429: TooManyRequestsResponseResponse,
    500: {
      description: 'Internal Server Error',
      content: { 'application/json': { schema: HTTPCIAppErrorsSchema } },
    },
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: [] }],
})

