export const getApiV2DowntimeRoute = createRoute({
  method: 'get',
  path: '/api/v2/downtime',
  tags: ['Downtimes'],
  summary: 'Get all downtimes',
  description: 'Get all scheduled downtimes.',
  operationId: 'ListDowntimes',
  request: {
    query: z.object({
      current_only: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description: 'Only return downtimes that are active when the request is made.',
            in: 'query',
            name: 'current_only',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
      include: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Comma-separated list of resource paths for related resources to include in the response. Supported resource\npaths are `created_by` and `monitor`.',
            in: 'query',
            name: 'include',
            required: false,
            schema: { example: 'created_by,monitor', type: 'string' },
          },
          example: 'created_by,monitor',
        }),
      'page[offset]': PageOffsetParamsSchema,
      'page[limit]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(30n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Maximum number of downtimes in the response.',
            example: 100,
            in: 'query',
            name: 'page[limit]',
            required: false,
            schema: { default: 30, format: 'int64', type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: ListDowntimesResponseSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      created: '2024-01-01T00:00:00+00:00',
                      display_timezone: 'America/New_York',
                      message: 'Message about the downtime',
                      modified: '2024-01-01T00:00:00+00:00',
                      monitor_identifier: { monitor_tags: ['*'] },
                      mute_first_recovery_notification: false,
                      notify_end_states: ['alert', 'warn'],
                      notify_end_types: ['canceled', 'expired'],
                      scope: 'env:(staging OR prod) AND datacenter:us-east-1',
                      status: 'active',
                    },
                    id: '00000000-0000-1234-0000-000000000000',
                    type: 'downtime',
                  },
                ],
                meta: { page: { total_filtered_count: 1 } },
              },
            },
          },
        },
      },
    },
    403: {
      description: 'Forbidden',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['monitors_downtime'] }],
})

