export const getApiV2EventsRoute = createRoute({
  method: 'get',
  path: '/api/v2/events',
  tags: ['Events'],
  summary: 'Get a list of events',
  description:
    'List endpoint returns events that match an events search query.\n[Results are paginated similarly to logs](https://docs.datadoghq.com/logs/guide/collect-multiple-logs-with-pagination).\n\nUse this endpoint to see your latest events.',
  operationId: 'ListEvents',
  request: {
    query: z.object({
      'filter[query]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Search query following events syntax.',
            in: 'query',
            name: 'filter[query]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[from]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Minimum timestamp for requested events, in milliseconds.',
            in: 'query',
            name: 'filter[from]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[to]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Maximum timestamp for requested events, in milliseconds.',
            in: 'query',
            name: 'filter[to]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      sort: EventsSortSchema.openapi({
        param: {
          description: 'Order of events in results.',
          in: 'query',
          name: 'sort',
          required: false,
          schema: { $ref: '#/components/schemas/EventsSort' },
        },
      }).exactOptional(),
      'page[cursor]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'List following results with a cursor provided in the previous query.',
            example:
              'eyJzdGFydEF0IjoiQVFBQUFYS2tMS3pPbm40NGV3QUFBQUJCV0V0clRFdDZVbG8zY3pCRmNsbHJiVmxDWlEifQ==',
            in: 'query',
            name: 'page[cursor]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'page[limit]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().max(1000),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            description: 'Maximum number of events in the response.',
            example: 25,
            in: 'query',
            name: 'page[limit]',
            required: false,
            schema: { default: 10, format: 'int32', maximum: 1000, type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: EventsListResponseSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      message: 'Test event',
                      tags: ['env:prod'],
                      timestamp: '2019-01-02T09:42:36.320Z',
                    },
                    id: 'AAAAAWgN8Xwgr1vKDQAAAABBV2dOOFh3ZzZobm1mWXJFYTR0OA',
                    type: 'event',
                  },
                ],
                meta: {
                  request_id: 'MWlFUjVaWGZTTTZPYzM0VXp1OXU2d3xLSVpEMjZKQ0VKUTI0dEYtM3RSOFVR',
                },
              },
            },
          },
        },
      },
    },
    400: BadRequestResponseResponse,
    403: NotAuthorizedResponseResponse,
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['events_read'] }],
})

