export const getApiV2FleetAgentsRoute = createRoute({
  method: 'get',
  path: '/api/v2/fleet/agents',
  tags: ['Fleet Automation'],
  summary: 'List all Datadog Agents',
  description:
    'Retrieve a paginated list of Datadog Agents.\n\nReturns agents with support for pagination, sorting, and filtering.\nUse `page_number` and `page_size` to navigate pages, `filter` to narrow by field values,\nand `tags` to filter by agent tags.',
  operationId: 'ListFleetAgentsV2',
  request: {
    query: z.object({
      page_number: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(0n))
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Page number for pagination, starting at 0.',
            in: 'query',
            name: 'page_number',
            required: false,
            schema: { default: 0, format: 'int64', minimum: 0, type: 'integer' },
          },
        }),
      page_size: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(1n).max(100n))
        .default(10n)
        .exactOptional()
        .openapi({
          param: {
            description:
              'Number of agents to return per page. Maximum value is 100. Defaults to 10.',
            in: 'query',
            name: 'page_size',
            required: false,
            schema: { default: 10, format: 'int64', maximum: 100, minimum: 1, type: 'integer' },
          },
        }),
      filter: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter string to narrow down agent results.',
            example: 'hostname:my-hostname OR env:dev',
            in: 'query',
            name: 'filter',
            required: false,
            schema: { type: 'string' },
          },
        }),
      tags: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              "Comma-separated list of tag keys to select which tags are included in each agent's `tags` attribute. Does not filter which agents are returned.",
            in: 'query',
            name: 'tags',
            required: false,
            schema: { type: 'string' },
          },
        }),
      sort_attribute: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Agent attribute to sort results by. Must be a supported attribute name; unsupported values return a 400 error.',
            in: 'query',
            name: 'sort_attribute',
            required: false,
            schema: { type: 'string' },
          },
        }),
      sort_descending: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Set to `true` to sort results in descending order. Defaults to ascending.',
            in: 'query',
            name: 'sort_descending',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: FleetAgentsV2ResponseSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      agent_version: '7.50.0',
                      api_key_name: 'Production API Key',
                      api_key_uuid: 'a1b2c3d4-e5f6-4321-a123-123456789abc',
                      cloud_provider: 'aws',
                      datadog_data_center: 'us1',
                      enabled_products: ['apm', 'logs'],
                      env: ['prod'],
                      first_seen_at: 1699900000,
                      fleet_policies: [],
                      hostname: 'my-hostname',
                      integrations: ['mysql'],
                      ip_addresses: ['10.0.0.1'],
                      is_single_step_instrumentation_enabled: false,
                      last_restart_at: 1699999999,
                      os: 'linux',
                      otel_collector_versions: [],
                      remote_agent_management: 'enabled',
                      remote_config_status: 'connected',
                      services: ['web'],
                      tags: [{ key: 'team', value: 'platform' }],
                    },
                    id: 'my-agent-hostname',
                    type: 'agent',
                  },
                ],
                meta: { page: { total_count: 500, total_filtered_count: 1 } },
              },
            },
          },
        },
      },
    },
    400: BadRequestResponseResponse,
    401: UnauthorizedResponseResponse,
    403: ForbiddenResponseResponse,
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: [] }],
})

