export const getApiV2GovernanceControlDetectionTypeDetectionsRoute = createRoute({
  method: 'get',
  path: '/api/v2/governance/control/{detection_type}/detections',
  tags: ['Governance Console'],
  summary: 'List control detections',
  description:
    'Retrieve the detections produced by the governance control with the given detection type.\nResults can be filtered by state and free-text query, sorted, and paginated.',
  operationId: 'ListGovernanceControlDetections',
  request: {
    params: z.object({
      detection_type: z
        .string()
        .openapi({
          param: {
            description:
              'The detection type that identifies the control; for example, `unused_api_keys`.',
            example: 'unused_api_keys',
            in: 'path',
            name: 'detection_type',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      'filter[state]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Restrict the results to detections in the given state.',
            example: 'active',
            in: 'query',
            name: 'filter[state]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[query]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Restrict the results to detections matching the given free-text query.',
            example: 'production',
            in: 'query',
            name: 'filter[query]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      sort: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'A comma-separated list of attributes to sort detections by. Prefix an attribute with\n`-` for descending order.\n\nThe attributes available for sorting are `id`, `created_at`, `assigned_to`,\n`detection_type`, `display_name`, `exception_at`, `mitigate_after`, `mitigated_at`,\n`priority`, `resource_id`, and `state`. Defaults to `created_at,-id`.',
            example: '-created_at,-id',
            in: 'query',
            name: 'sort',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'page[number]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description: 'The zero-based index of the page to return; the first page is 0.',
            example: 0,
            in: 'query',
            name: 'page[number]',
            required: false,
            schema: { default: 0, format: 'int64', type: 'integer' },
          },
        }),
      'page[size]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description: 'The number of detections to return per page.',
            example: 50,
            in: 'query',
            name: 'page[size]',
            required: false,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: GovernanceControlDetectionsResponseSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      assigned_team: 'platform-security',
                      assigned_to: '11111111-2222-3333-4444-555555555555',
                      assignment_source: 'manual',
                      control_id: 'unused_api_keys',
                      created_at: '2024-03-01T12:00:00Z',
                      detection_type: 'unused_api_keys',
                      display_name: 'CI Deploy Key',
                      metadata: { region: 'us-east-1' },
                      priority: 1,
                      resource_id: 'api-key-12345',
                      resource_type: 'api_key',
                      state: 'active',
                    },
                    id: '3f9b2c1a-8d4e-4a6b-9c2f-1e7d5a0b3c4d',
                    type: 'governance_control_detection',
                  },
                ],
              },
            },
          },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    401: {
      description: 'Unauthorized',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    403: {
      description: 'Forbidden',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: [] }],
})

