export const getApiV2LlmObsV1ProjectsRoute = createRoute({
  method: 'get',
  path: '/api/v2/llm-obs/v1/projects',
  tags: ['Agent Observability'],
  summary: 'List Agent Observability projects',
  description: 'List all Agent Observability projects sorted by creation date, newest first.',
  operationId: 'ListLLMObsProjects',
  request: {
    query: z.object({
      'filter[id]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter projects by project ID.',
            in: 'query',
            name: 'filter[id]',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'filter[name]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter projects by name.',
            in: 'query',
            name: 'filter[name]',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'page[cursor]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Use the Pagination cursor to retrieve the next page of results.',
            in: 'query',
            name: 'page[cursor]',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'page[limit]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description: 'Maximum number of results to return per page.',
            in: 'query',
            name: 'page[limit]',
            schema: { format: 'int64', type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: LLMObsProjectsResponseSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      created_at: '2024-01-01T00:00:00+00:00',
                      description: '',
                      name: 'My LLM Project',
                      updated_at: '2024-01-01T00:00:00+00:00',
                    },
                    id: '00000000-0000-0000-0000-000000000001',
                    type: 'projects',
                  },
                ],
              },
            },
          },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    401: {
      description: 'Unauthorized',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    403: {
      description: 'Forbidden',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: [] }],
})

