export const getApiV2LlmObsV1ProjectIdDatasetsDatasetIdExportRoute = createRoute({
  method: 'get',
  path: '/api/v2/llm-obs/v1/{project_id}/datasets/{dataset_id}/export',
  tags: ['Agent Observability'],
  summary: 'Export an Agent Observability dataset',
  description:
    'Download the contents of a dataset as a CSV file. The download is streamed and includes one row per dataset record.',
  operationId: 'ExportLLMObsDataset',
  request: {
    params: z.object({
      project_id: z
        .string()
        .openapi({
          param: {
            description: 'The ID of the Agent Observability project.',
            example: 'a33671aa-24fd-4dcd-9b33-a8ec7dde7751',
            in: 'path',
            name: 'project_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
      dataset_id: z
        .string()
        .openapi({
          param: {
            description: 'The ID of the Agent Observability dataset.',
            example: '9f64e5c7-dc5a-45c8-a17c-1b85f0bec97d',
            in: 'path',
            name: 'dataset_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      format: LLMObsDatasetExportFormatSchema.openapi({
        param: {
          description: 'Export format for the dataset contents. Only `csv` is currently supported.',
          in: 'query',
          name: 'format',
          schema: { $ref: '#/components/schemas/LLMObsDatasetExportFormat' },
          required: false,
        },
      }).exactOptional(),
      version: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().max(2147483647n))
        .exactOptional()
        .openapi({
          param: {
            description:
              'Version of the dataset to export. If omitted, the current version is used. Must be between 0 and the current version of the dataset, inclusive.',
            in: 'query',
            name: 'version',
            schema: { format: 'int64', maximum: 2147483647, type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'text/csv': {
          schema: z.string(),
          examples: {
            default: {
              value: 'id,input,expected_output,metadata,tags\nrec-1,"What is 2+2?","4",{},""',
            },
          },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    401: {
      description: 'Unauthorized',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    403: {
      description: 'Forbidden',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    404: {
      description: 'Not Found',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
    500: {
      description: 'Internal Server Error',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: [] }],
})

