export const postApiV2LlmObsV2ProjectIdDatasetsDatasetIdRecordsUploadRoute = createRoute({
  method: 'post',
  path: '/api/v2/llm-obs/v2/{project_id}/datasets/{dataset_id}/records/upload',
  tags: ['Agent Observability'],
  summary: 'Upload records to an Agent Observability dataset',
  description:
    'Upload records to a dataset from a file. The request is a `multipart/form-data` upload containing a single `file` part.\nCurrently only CSV is supported. The CSV must include an `input` column. Optional columns are `id`, `expected_output`, `metadata`, and `tags`.\n\nThe response is a Server-Sent Events stream (`text/event-stream`) emitting progress updates while records are processed. The stream emits the following named events:\n  - `progress`: incremental record counts written so far.\n  - `completed`: terminal event with a JSON body containing `records_created`.\n  - `error`: terminal event with a JSON body containing an error `message`.',
  operationId: 'UploadLLMObsDatasetRecordsFile',
  request: {
    params: z.object({
      project_id: z
        .string()
        .openapi({
          param: {
            description: 'The ID of the Agent Observability project.',
            example: 'a33671aa-24fd-4dcd-9b33-a8ec7dde7751',
            in: 'path',
            name: 'project_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
      dataset_id: z
        .string()
        .openapi({
          param: {
            description: 'The ID of the Agent Observability dataset.',
            example: '9f64e5c7-dc5a-45c8-a17c-1b85f0bec97d',
            in: 'path',
            name: 'dataset_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      deduplicate: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description:
              'Whether to skip records whose `input` already exists in the dataset. Defaults to `false`.',
            in: 'query',
            name: 'deduplicate',
            schema: { default: false, type: 'boolean' },
            required: false,
          },
        }),
      overwrite: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            description:
              'Whether to overwrite existing records that share the same user-provided `id`. Defaults to `true`.',
            in: 'query',
            name: 'overwrite',
            schema: { default: true, type: 'boolean' },
            required: false,
          },
        }),
      tags: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'Tags to apply to every uploaded record, in addition to any tags defined on individual rows. Can be repeated, e.g. `tags=env:prod&tags=team:ai`.',
            in: 'query',
            name: 'tags',
            schema: { items: { type: 'string' }, type: 'array' },
            required: false,
          },
        }),
      'include[user_data]': z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description: 'Whether to enrich the response with user metadata.',
            in: 'query',
            name: 'include[user_data]',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
    }),
    body: {
      description: 'Multipart upload payload containing the records file.',
      content: {
        'multipart/form-data': {
          schema: LLMObsDatasetRecordsUploadFileSchema,
          examples: { default: { value: { file: 'records.csv' } } },
        },
      },
      required: true,
    },
  },
  responses: {
    200: { description: 'OK' },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    401: {
      description: 'Unauthorized',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    403: {
      description: 'Forbidden',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    404: {
      description: 'Not Found',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
    500: {
      description: 'Internal Server Error',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: [] }],
})

export const getApiV2LlmObsV3ExperimentsExperimentIdEventsRoute = createRoute({
  method: 'get',
  path: '/api/v2/llm-obs/v3/experiments/{experiment_id}/events',
  tags: ['Agent Observability'],
  summary: 'List events for an Agent Observability experiment',
  description:
    'Retrieve spans and experiment-level summary metrics for a given experiment with cursor-based pagination.',
  operationId: 'ListLLMObsExperimentEvents',
  request: {
    params: z.object({ experiment_id: LLMObsExperimentIDPathParameterParamsSchema }),
    query: z.object({
      'page[limit]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(5000n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Maximum number of spans to return per page. Defaults to 5000.',
            in: 'query',
            name: 'page[limit]',
            schema: { default: 5000, format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      'page[cursor]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Opaque cursor from a previous response to fetch the next page of results.',
            in: 'query',
            name: 'page[cursor]',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: LLMObsExperimentEventsV2ResponseSchema,
          examples: {
            default: {
              value: {
                data: {
                  attributes: {
                    spans: [
                      {
                        duration: 1500000000,
                        eval_metrics: [],
                        id: '00000000-0000-0000-0000-000000000002',
                        name: 'llm_call',
                        span_id: 'span-7a1b2c3d',
                        start_ns: 1705314600000000000,
                        status: 'ok',
                        tags: [],
                        trace_id: 'abc123def456',
                      },
                    ],
                    summary_metrics: [],
                  },
                  id: '00000000-0000-0000-0000-000000000001',
                  type: 'experiment_events',
                },
                meta: { after: null },
              },
            },
          },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    401: {
      description: 'Unauthorized',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    403: {
      description: 'Forbidden',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    404: {
      description: 'Not Found',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
    500: {
      description: 'Internal Server Error',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: [] }],
})

