export const getApiV2LogsEventsRoute = createRoute({
  method: 'get',
  path: '/api/v2/logs/events',
  tags: ['Logs'],
  summary: 'Search logs (GET)',
  description:
    'List endpoint returns logs that match a log search query.\n[Results are paginated][1].\n\nUse this endpoint to search and filter your logs.\n\n**If you are considering archiving logs for your organization,\nconsider use of the Datadog archive capabilities instead of the log list API.\nSee [Datadog Logs Archive documentation][2].**\n\n[1]: /logs/guide/collect-multiple-logs-with-pagination\n[2]: https://docs.datadoghq.com/logs/archives',
  operationId: 'ListLogsGet',
  request: {
    query: z.object({
      'filter[query]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Search query following logs syntax.',
            example: '@datacenter:us @role:db',
            in: 'query',
            name: 'filter[query]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[indexes]': z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string().openapi({ description: 'The name of a log index.' })),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              "For customers with multiple indexes, the indexes to search.\nDefaults to '*' which means all indexes",
            example: ['main', 'web'],
            explode: false,
            in: 'query',
            name: 'filter[indexes]',
            required: false,
            schema: {
              items: { description: 'The name of a log index.', type: 'string' },
              type: 'array',
            },
          },
        }),
      'filter[from]': z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            description: 'Minimum timestamp for requested logs.',
            example: '2019-01-02T09:42:36.320Z',
            in: 'query',
            name: 'filter[from]',
            required: false,
            schema: { format: 'date-time', type: 'string' },
          },
        }),
      'filter[to]': z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            description: 'Maximum timestamp for requested logs.',
            example: '2019-01-03T09:42:36.320Z',
            in: 'query',
            name: 'filter[to]',
            required: false,
            schema: { format: 'date-time', type: 'string' },
          },
        }),
      'filter[storage_tier]': LogsStorageTierSchema.openapi({
        param: {
          description: 'Specifies the storage type to be used',
          example: 'indexes',
          in: 'query',
          name: 'filter[storage_tier]',
          required: false,
          schema: { $ref: '#/components/schemas/LogsStorageTier' },
        },
      }).exactOptional(),
      sort: LogsSortSchema.openapi({
        param: {
          description: 'Order of logs in results.',
          in: 'query',
          name: 'sort',
          required: false,
          schema: { $ref: '#/components/schemas/LogsSort' },
        },
      }).exactOptional(),
      'page[cursor]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'List following results with a cursor provided in the previous query.',
            example:
              'eyJzdGFydEF0IjoiQVFBQUFYS2tMS3pPbm40NGV3QUFBQUJCV0V0clRFdDZVbG8zY3pCRmNsbHJiVmxDWlEifQ==',
            in: 'query',
            name: 'page[cursor]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'page[limit]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().max(5000),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            description: 'Maximum number of logs in the response.',
            example: 25,
            in: 'query',
            name: 'page[limit]',
            required: false,
            schema: { default: 10, format: 'int32', maximum: 5000, type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: LogsListResponseSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      message: 'Hello World',
                      service: 'web-app',
                      tags: ['env:prod'],
                      timestamp: '2024-01-01T00:00:00+00:00',
                    },
                    id: 'AAAAAWgN8Xwgr1vKDQAAAABBV2dOOFh3ZzZobm1mWXJFYTR0OA',
                    type: 'log',
                  },
                ],
                meta: { elapsed: 132, status: 'done' },
              },
            },
          },
        },
      },
    },
    400: BadRequestResponseResponse,
    403: NotAuthorizedResponseResponse,
    429: TooManyRequestsResponseResponse,
  },
})

