export const getApiV2MetricsMetricNameEstimateRoute = createRoute({
  method: 'get',
  path: '/api/v2/metrics/{metric_name}/estimate',
  tags: ['Metrics'],
  summary: 'Tag Configuration Cardinality Estimator',
  description:
    'Returns the estimated cardinality for a metric with a given tag, percentile and number of aggregations configuration using Metrics without Limits&trade;.',
  operationId: 'EstimateMetricsOutputSeries',
  request: {
    params: z.object({ metric_name: MetricNameParamsSchema }),
    query: z.object({
      'filter[groups]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Comma-separated list of tag keys that the metric is configured to query with. For example: `filter[groups]=app,host`.',
            example: 'app,host',
            in: 'query',
            name: 'filter[groups]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[exclude_tags_mode]': z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description:
              'When `true`, `filter[groups]` is treated as an exclude list instead of an include list. Defaults to `false`.',
            example: false,
            in: 'query',
            name: 'filter[exclude_tags_mode]',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
      'filter[hours_ago]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(49).max(2147483647),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'The number of hours of look back (from now) to estimate cardinality with. If unspecified, it defaults to 0 hours.',
            example: 49,
            in: 'query',
            name: 'filter[hours_ago]',
            required: false,
            schema: { format: 'int32', maximum: 2147483647, minimum: 49, type: 'integer' },
          },
        }),
      'filter[num_aggregations]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().max(9),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Deprecated. Number of aggregations has no impact on volume.',
            example: 1,
            in: 'query',
            name: 'filter[num_aggregations]',
            required: false,
            schema: { format: 'int32', maximum: 9, type: 'integer' },
          },
        }),
      'filter[pct]': z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description: 'Deprecated. This query parameter has no effect on the estimate.',
            example: true,
            in: 'query',
            name: 'filter[pct]',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
      'filter[timespan_h]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().max(2147483647),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'A window, in hours, from the look back to estimate cardinality with. The minimum and default is 1 hour.',
            example: 6,
            in: 'query',
            name: 'filter[timespan_h]',
            required: false,
            schema: { format: 'int32', maximum: 2147483647, type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success',
      content: {
        'application/json': {
          schema: MetricEstimateResponseSchema,
          examples: {
            default: {
              value: {
                data: {
                  attributes: {
                    estimate_type: 'count_or_gauge',
                    estimated_at: '2024-01-01T00:00:00+00:00',
                    estimated_output_series: 50,
                  },
                  id: 'system.cpu.user',
                  type: 'metric_cardinality_estimate',
                },
              },
            },
          },
        },
      },
    },
    400: {
      description: 'API error response.',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
    403: {
      description: 'API error response.',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
    404: {
      description: 'API error response.',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
    429: {
      description: 'Too Many Requests',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
  },
})

