export const getApiV2MonitorMonitorIdDowntimeMatchesRoute = createRoute({
  method: 'get',
  path: '/api/v2/monitor/{monitor_id}/downtime_matches',
  tags: ['Downtimes'],
  summary: 'Get active downtimes for a monitor',
  description: 'Get all active downtimes for the specified monitor.',
  operationId: 'ListMonitorDowntimes',
  request: {
    params: z.object({
      monitor_id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description: 'The id of the monitor.',
            in: 'path',
            name: 'monitor_id',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
    query: z.object({
      'page[offset]': PageOffsetParamsSchema,
      'page[limit]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(30n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Maximum number of downtimes in the response.',
            example: 100,
            in: 'query',
            name: 'page[limit]',
            required: false,
            schema: { default: 30, format: 'int64', type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: MonitorDowntimeMatchResponseSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      end: '2024-01-01T01:00:00+00:00',
                      groups: ['service:postgres'],
                      scope: 'env:(staging OR prod) AND datacenter:us-east-1',
                      start: '2024-01-01T00:00:00+00:00',
                    },
                    id: '00000000-0000-1234-0000-000000000000',
                    type: 'downtime_match',
                  },
                ],
                meta: { page: { total_filtered_count: 1 } },
              },
            },
          },
        },
      },
    },
    404: {
      description: 'Monitor Not Found error',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['monitors_downtime'] }],
})

