export const getApiV2NetworkConnectionsAggregateRoute = createRoute({
  method: 'get',
  path: '/api/v2/network/connections/aggregate',
  tags: ['Cloud Network Monitoring'],
  summary: 'Get all aggregated connections',
  description: 'Get all aggregated connections.',
  operationId: 'GetAggregatedConnections',
  request: {
    query: z.object({
      from: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description:
              'Unix timestamp (number of seconds since epoch) of the start of the query window. If not provided, the start of the query window is 15 minutes before the `to` timestamp. If neither `from` nor `to` are provided, the query window is `[now - 15m, now]`.',
            in: 'query',
            name: 'from',
            schema: { format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      to: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description:
              'Unix timestamp (number of seconds since epoch) of the end of the query window. If not provided, the end of the query window is the current time. If neither `from` nor `to` are provided, the query window is `[now - 15m, now]`.',
            in: 'query',
            name: 'to',
            schema: { format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      group_by: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Comma-separated list of fields to group connections by. The maximum number of group_by(s) is 10.',
            in: 'query',
            name: 'group_by',
            schema: { type: 'string' },
            required: false,
          },
        }),
      tags: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Comma-separated list of tags to filter connections by.',
            in: 'query',
            name: 'tags',
            schema: { type: 'string' },
            required: false,
          },
        }),
      query: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Free-form search query using AND/OR/NOT operators, wildcards, and parentheses. When provided, takes precedence over the `tags` parameter.',
            example: '(client_team:networks OR client_team:platform) AND server_service:hucklebuck',
            in: 'query',
            name: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1).max(7500),
        )
        .default(100)
        .exactOptional()
        .openapi({
          param: {
            description:
              'The number of connections to be returned. The maximum value is 7500. The default is 100.',
            in: 'query',
            name: 'limit',
            schema: { default: 100, format: 'int32', maximum: 7500, minimum: 1, type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: SingleAggregatedConnectionResponseArraySchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      bytes_sent_by_client: 100,
                      bytes_sent_by_server: 200,
                      packets_sent_by_client: 10,
                      packets_sent_by_server: 20,
                    },
                    id: 'abc-123',
                    type: 'aggregated_connection',
                  },
                ],
              },
            },
          },
        },
      },
    },
    400: BadRequestResponseResponse,
    403: ForbiddenResponseResponse,
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['network_connections_read'] }],
})

