export const getApiV2OnCallEscalationPoliciesRoute = createRoute({
  method: 'get',
  path: '/api/v2/on-call/escalation-policies',
  tags: ['On-Call'],
  summary: 'List On-Call escalation policies',
  description: 'Retrieve a paginated list of On-Call escalation policies, sorted by name.',
  operationId: 'ListOnCallEscalationPolicies',
  request: {
    query: z.object({
      'page[size]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().max(50n))
        .default(20n)
        .exactOptional()
        .openapi({
          param: {
            description:
              'Number of escalation policies to return per page. The maximum allowed value is 50.',
            in: 'query',
            name: 'page[size]',
            required: false,
            schema: { default: 20, example: 20, format: 'int64', maximum: 50, type: 'integer' },
          },
          example: 20,
        }),
      'page[number]': PageNumberParamsSchema,
      'filter[query]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              "Search query to filter escalation policies. Supports free-text search on the policy name (case-insensitive) and structured filters on `team.id` and `tags`. When set, `filter[team_id]`, `filter[user_id]`, and `filter[schedule_id]` are ignored. Can't be combined with `filter[tags]` or `filter[tags_any]`.",
            in: 'query',
            name: 'filter[query]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[team_id]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Comma-separated list of team IDs. Returns escalation policies that belong to any of these teams or have a step targeting any of them.',
            in: 'query',
            name: 'filter[team_id]',
            required: false,
            schema: { example: '00000000-da3a-0000-0000-000000000000', type: 'string' },
          },
          example: '00000000-da3a-0000-0000-000000000000',
        }),
      'filter[user_id]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Comma-separated list of user IDs. Returns escalation policies with a step targeting any of these users.',
            in: 'query',
            name: 'filter[user_id]',
            required: false,
            schema: { example: '00000000-aba1-0000-0000-000000000000', type: 'string' },
          },
          example: '00000000-aba1-0000-0000-000000000000',
        }),
      'filter[schedule_id]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Comma-separated list of schedule IDs. Returns escalation policies with a step targeting any of these schedules.',
            in: 'query',
            name: 'filter[schedule_id]',
            required: false,
            schema: { example: '00000000-aba2-0000-0000-000000000000', type: 'string' },
          },
          example: '00000000-aba2-0000-0000-000000000000',
        }),
      'filter[tags]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Comma-separated list of `key:value` tags. Returns escalation policies that have all of these tags.',
            in: 'query',
            name: 'filter[tags]',
            required: false,
            schema: { example: 'env:prod', type: 'string' },
          },
          example: 'env:prod',
        }),
      'filter[tags_any]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Comma-separated list of `key:value` tags. Returns escalation policies that have at least one of these tags.',
            in: 'query',
            name: 'filter[tags_any]',
            required: false,
            schema: { example: 'env:prod,env:staging', type: 'string' },
          },
          example: 'env:prod,env:staging',
        }),
      include: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Comma-separated list of included relationships to be returned. Allowed values: `teams`, `steps`, `steps.targets`, `steps.targets.schedule`, `user.color`. `user.color` populates the `color` attribute of users included through `steps.targets`.',
            in: 'query',
            name: 'include',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: EscalationPoliciesSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      name: 'Escalation Policy 1',
                      resolve_page_on_policy_end: true,
                      retries: 2,
                      tags: ['env:prod'],
                    },
                    id: '00000000-aba1-0000-0000-000000000000',
                    relationships: {
                      steps: {
                        data: [{ id: '00000000-aba1-0000-0000-000000000000', type: 'steps' }],
                      },
                      teams: {
                        data: [{ id: '00000000-da3a-0000-0000-000000000000', type: 'teams' }],
                      },
                    },
                    type: 'policies',
                  },
                ],
                meta: {
                  page: {
                    first_number: 0,
                    last_number: 0,
                    next_number: null,
                    number: 0,
                    prev_number: null,
                    size: 20,
                    total: 1,
                    type: 'number_size',
                  },
                },
              },
            },
          },
        },
      },
    },
    400: BadRequestResponseResponse,
    401: UnauthorizedResponseResponse,
    403: ForbiddenResponseResponse,
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: [] }],
})

