export const postApiV2OrgDisableRoute = createRoute({
  method: 'post',
  path: '/api/v2/org/disable',
  tags: ['Customer Org'],
  summary: 'Disable the authenticated customer organization',
  description:
    'Disable the Datadog organization associated with the authenticated user or API key.\nThe request body uses JSON:API format. If `org_uuid` is supplied, it must match\nthe authenticated org or the request is rejected. Successful calls disable the org\nand return the resulting state from the downstream service. Requires the\n`org_management` permission.\n\n**Limitations**:\n\n- **Organization age**: Only organizations created within the last 10 days can be disabled\n  through this endpoint. This restriction is a safeguard against accidentally disabling\n  long-running organizations. Attempting to disable an older organization returns a `403 Forbidden`.\n- **Feature flag**: The feature flag `org_disable_self_service_enabled` must be enabled for the\n  target organization or one of its ancestor organizations. Contact\n  [Datadog support](https://docs.datadoghq.com/help/) to enable this for your organization.\n  Requests for organizations without this flag return a `403 Forbidden`.\n- **Already-disabled organizations**: If the target organization is already disabled, the request\n  returns a `409 Conflict`.',
  operationId: 'DisableCustomerOrg',
  request: {
    body: {
      content: {
        'application/json': {
          schema: CustomerOrgDisableRequestSchema,
          examples: {
            default: {
              value: {
                data: {
                  attributes: { org_uuid: 'abcdef01-2345-6789-abcd-ef0123456789' },
                  id: '1',
                  type: 'customer_org_disable',
                },
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: CustomerOrgDisableResponseSchema,
          examples: {
            default: {
              value: {
                data: {
                  attributes: { status: 'disabled' },
                  id: 'abcdef01-2345-6789-abcd-ef0123456789',
                  type: 'org_disable',
                },
              },
            },
          },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    401: {
      description: 'Unauthorized',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    403: {
      description: 'Forbidden',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    409: {
      description: 'Conflict',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
    500: {
      description: 'Internal Server Error',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['org_management'] }],
})

