export const getApiV2ProcessesRoute = createRoute({
  method: 'get',
  path: '/api/v2/processes',
  tags: ['Processes'],
  summary: 'Get all processes',
  description:
    "Get processes collected by Live Processes for your organization. One request covers a window of\nat most 1 hour that starts within the past 36 hours. To cover a longer period, make one request\nper hour. Older data is not available from this endpoint.\n\nWhen a process includes `identifying_tags`, pass them as `tag_filters` in a `process` data source\nquery to `/api/v2/query/scalar` or `/api/v2/query/timeseries` to get CPU or memory metrics for that\none process. If absent, don't substitute an empty filter, which would query all processes.",
  operationId: 'ListProcesses',
  request: {
    query: z.object({
      search: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Free-text search over process fields such as the executable and user. When it contains several\nwords, a process must match all of them. Use `tags` for exact values such as host.',
            in: 'query',
            name: 'search',
            required: false,
            schema: { type: 'string' },
          },
        }),
      tags: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Comma-separated `key:value` tags. A process must match every tag. Wildcards, negation\n(`-key:value`), spaces, and `IN (...)` are not supported. To cover several hosts, make one\nrequest per host.',
            example: 'account:prod,user:admin',
            in: 'query',
            name: 'tags',
            required: false,
            schema: { type: 'string' },
          },
        }),
      from: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description:
              'Start of the query window, in Unix seconds. Must be within the past 36 hours and at most 1 hour\nbefore `to`. If not provided, the start of the query window is 15 minutes before the `to` timestamp.\nIf neither `from` nor `to` is provided, the query window is `[now - 15m, now]`.',
            in: 'query',
            name: 'from',
            required: false,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
      to: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description:
              'End of the query window, in Unix seconds. Must be at most 1 hour after `from`. If not provided, the\nend of the query window is 15 minutes after the `from` timestamp. If neither `from` nor `to` is\nprovided, the query window is `[now - 15m, now]`.',
            in: 'query',
            name: 'to',
            required: false,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
      'page[limit]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1).max(10000),
        )
        .default(1000)
        .exactOptional()
        .openapi({
          param: {
            description: 'Maximum number of results returned.',
            in: 'query',
            name: 'page[limit]',
            required: false,
            schema: { default: 1000, format: 'int32', maximum: 10000, minimum: 1, type: 'integer' },
          },
        }),
      'page[cursor]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'String to query the next page of results.\nThis key is provided with each valid response from the API in `meta.page.after`.',
            in: 'query',
            name: 'page[cursor]',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: ProcessSummariesResponseSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      cmdline: '/usr/bin/python3',
                      executable: '/usr/bin/python3',
                      host: 'my-host',
                      identifying_tags: ['host:my-host', 'pid:123'],
                      pid: 123,
                    },
                    id: 'abc-123',
                    type: 'process',
                  },
                ],
              },
            },
          },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
    403: {
      description: 'Authentication Error',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: [] }],
})

