export const getApiV2PrunedTraceTraceIdRoute = createRoute({
  method: 'get',
  path: '/api/v2/pruned_trace/{trace_id}',
  tags: ['APM Trace'],
  summary: 'Get a pruned trace by ID',
  description:
    'Retrieve a pruned, hierarchical view of an APM trace by its trace ID.\nThe trace is summarized as a tree of spans rooted at the trace root and reduced in size\nto keep rendering large traces in the UI practical.\nA `400 Bad Request` response means the trace ID is malformed. A `404 Not Found` response means\nno trace with this ID is available, such as when the trace is outside the retention period.\nThis endpoint is rate limited to `60` requests per minute per organization.',
  operationId: 'GetPrunedTraceByID',
  request: {
    params: z.object({ trace_id: TraceIDPathParameterParamsSchema }),
    query: z.object({
      expand_span_id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description:
              'Span ID to expand and preserve in the pruned tree even when its branch would\nnormally be summarized.',
            example: 9876543210987655000,
            in: 'query',
            name: 'expand_span_id',
            required: false,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
      time_hint: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().max(2147483647),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'Optional Unix time hint, in seconds, used to optimize the lookup of the trace\nin long-term storage.',
            example: 1716800000,
            in: 'query',
            name: 'time_hint',
            required: false,
            schema: { format: 'int32', maximum: 2147483647, type: 'integer' },
          },
        }),
      force_source: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Force the trace to be loaded from a specific source. When unset, the API picks\nthe source automatically.',
            example: 'driveline',
            in: 'query',
            name: 'force_source',
            required: false,
            schema: { type: 'string' },
          },
        }),
      include_path: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'Restrict the pruned tree to spans matching the given `key:value` pairs.\nValues may be passed as repeated query parameters.',
            example: ['service:web-store'],
            in: 'query',
            name: 'include_path',
            required: false,
            schema: { items: { type: 'string' }, type: 'array' },
          },
        }),
      tag_include: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'Regex patterns of tag keys whose values must be included in the pruned spans.\nValues may be passed as repeated query parameters.',
            example: ['^http\\.'],
            in: 'query',
            name: 'tag_include',
            required: false,
            schema: { items: { type: 'string' }, type: 'array' },
          },
        }),
      tag_exclude: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'Regex patterns of tag keys whose values must be excluded from the pruned spans.\nValues may be passed as repeated query parameters.',
            example: ['^_dd\\.'],
            in: 'query',
            name: 'tag_exclude',
            required: false,
            schema: { items: { type: 'string' }, type: 'array' },
          },
        }),
      only_service_entry_spans: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description:
              'When set to `true`, only service entry spans are included in the pruned tree.',
            example: false,
            in: 'query',
            name: 'only_service_entry_spans',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: PrunedTraceResponseSchema,
          examples: {
            default: {
              value: {
                data: {
                  attributes: {
                    is_truncated: false,
                    size_bytes: 12345,
                    summarized_trace: {
                      root: {
                        children: [],
                        durationSeconds: 0.5,
                        endTime: '2026-05-27T12:00:00.5Z',
                        error: 0,
                        hidden_child_spans_count: 0,
                        meta: { env: 'production' },
                        metrics: { 'http.status_code': 200 },
                        name: 'web.request',
                        parentID: 0,
                        resource: 'GET /products',
                        service: 'web-store',
                        spanID: 9876543210987655000,
                        span_kind: 'SERVER',
                        startTime: '2026-05-27T12:00:00Z',
                      },
                      traceId: '0000000000000000abc1230000000000',
                    },
                  },
                  id: '0000000000000000abc1230000000000',
                  type: 'pruned_trace',
                },
              },
            },
          },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    403: {
      description: 'Forbidden',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    404: {
      description: 'Not Found',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
    504: {
      description: 'Gateway Timeout',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['apm_read'] }],
})

