export const getApiV2ReferenceTablesTablesRoute = createRoute({
  method: 'get',
  path: '/api/v2/reference-tables/tables',
  tags: ['Reference Tables'],
  summary: 'List tables',
  description: 'List all reference tables in this organization.',
  operationId: 'ListTables',
  request: {
    query: z.object({
      'page[limit]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(1n).max(100n))
        .default(15n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Number of tables to return.',
            example: 15,
            in: 'query',
            name: 'page[limit]',
            required: false,
            schema: { default: 15, format: 'int64', maximum: 100, minimum: 1, type: 'integer' },
          },
        }),
      'page[offset]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(0n))
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Number of tables to skip for pagination.',
            example: 0,
            in: 'query',
            name: 'page[offset]',
            required: false,
            schema: { default: 0, format: 'int64', minimum: 0, type: 'integer' },
          },
        }),
      sort: ReferenceTableSortTypeSchema.openapi({
        param: {
          description:
            'Sort field and direction for the list of reference tables. Use field name for ascending, prefix with "-" for descending.',
          example: '-updated_at',
          in: 'query',
          name: 'sort',
          required: false,
          schema: { $ref: '#/components/schemas/ReferenceTableSortType' },
        },
      }).exactOptional(),
      'filter[status]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by table status.',
            example: 'DONE',
            in: 'query',
            name: 'filter[status]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[table_name][exact]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by exact table name match.',
            example: 'my_reference_table',
            in: 'query',
            name: 'filter[table_name][exact]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[table_name][contains]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by table name containing substring.',
            example: 'user',
            in: 'query',
            name: 'filter[table_name][contains]',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: TableResultV2ArraySchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: { status: 'DONE', table_name: 'my_reference_table' },
                    id: 'abc-123',
                    type: 'reference_table',
                  },
                ],
              },
            },
          },
        },
      },
    },
    403: ForbiddenResponseResponse,
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: [] }],
})

