export const getApiV2ReferenceTablesTablesIdRowsListRoute = createRoute({
  method: 'get',
  path: '/api/v2/reference-tables/tables/{id}/rows/list',
  tags: ['Reference Tables'],
  summary: 'List rows',
  description:
    'List all rows in a reference table using cursor-based pagination. Pass the `page[continuation_token]` from the previous response to fetch the next page on the same consistent snapshot. Returns 400 for tables with more than 10,000,000 rows.',
  operationId: 'ListReferenceTableRows',
  request: {
    params: z.object({
      id: z
        .string()
        .openapi({
          param: {
            description: 'Unique identifier of the reference table to list rows from.',
            example: '00000000-0000-0000-0000-000000000000',
            in: 'path',
            name: 'id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      'page[limit]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(1n).max(1000n))
        .default(100n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Number of rows to return per page. Defaults to 100, maximum is 1000.',
            example: 100,
            in: 'query',
            name: 'page[limit]',
            required: false,
            schema: { default: 100, format: 'int64', maximum: 1000, minimum: 1, type: 'integer' },
          },
        }),
      'page[continuation_token]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              "Opaque cursor from the previous response's next link. Pass this to retrieve the next page on the same consistent snapshot.",
            example: 'eyJzaWQiOjEyMzQ1LCJwayI6ImV4YW1wbGVfcGsifQ==',
            in: 'query',
            name: 'page[continuation_token]',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: ListRowsResponseSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      values: {
                        category: 'tor',
                        intention: 'suspicious',
                        ip_address: '102.130.113.9',
                      },
                    },
                    id: '102.130.113.9',
                    type: 'row',
                  },
                ],
                links: {
                  first: '/api/v2/reference-tables/tables/<TABLE_ID>/rows/list?page[limit]=100',
                  next: '/api/v2/reference-tables/tables/<TABLE_ID>/rows/list?page[continuation_token]=<NEXT_CONTINUATION_TOKEN>',
                  self: '/api/v2/reference-tables/tables/<TABLE_ID>/rows/list?page[continuation_token]=<CONTINUATION_TOKEN>',
                },
              },
            },
          },
        },
      },
    },
    400: BadRequestResponseResponse,
    403: ForbiddenResponseResponse,
    404: NotFoundResponseResponse,
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: [] }],
})

