export const getApiV2RumEventsRoute = createRoute({
  method: 'get',
  path: '/api/v2/rum/events',
  tags: ['RUM'],
  summary: 'Get a list of RUM events',
  description:
    'List endpoint returns events that match a RUM search query.\n[Results are paginated][1].\n\nUse this endpoint to see your latest RUM events.\n\n[1]: https://docs.datadoghq.com/logs/guide/collect-multiple-logs-with-pagination',
  operationId: 'ListRUMEvents',
  request: {
    query: z.object({
      'filter[query]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Search query following RUM syntax.',
            example: '@type:session @application_id:xxxx',
            in: 'query',
            name: 'filter[query]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[from]': z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            description: 'Minimum timestamp for requested events.',
            example: '2019-01-02T09:42:36.320Z',
            in: 'query',
            name: 'filter[from]',
            required: false,
            schema: { format: 'date-time', type: 'string' },
          },
        }),
      'filter[to]': z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            description: 'Maximum timestamp for requested events.',
            example: '2019-01-03T09:42:36.320Z',
            in: 'query',
            name: 'filter[to]',
            required: false,
            schema: { format: 'date-time', type: 'string' },
          },
        }),
      sort: RUMSortSchema.openapi({
        param: {
          description: 'Order of events in results.',
          in: 'query',
          name: 'sort',
          required: false,
          schema: { $ref: '#/components/schemas/RUMSort' },
        },
      }).exactOptional(),
      'page[cursor]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'List following results with a cursor provided in the previous query.',
            example:
              'eyJzdGFydEF0IjoiQVFBQUFYS2tMS3pPbm40NGV3QUFBQUJCV0V0clRFdDZVbG8zY3pCRmNsbHJiVmxDWlEifQ==',
            in: 'query',
            name: 'page[cursor]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'page[limit]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().max(1000),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            description: 'Maximum number of events in the response.',
            example: 25,
            in: 'query',
            name: 'page[limit]',
            required: false,
            schema: { default: 10, format: 'int32', maximum: 1000, type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: RUMEventsResponseSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: { service: 'test-service', timestamp: '2024-01-01T00:00:00+00:00' },
                    id: 'abc-123',
                    type: 'rum',
                  },
                ],
              },
            },
          },
        },
      },
    },
    400: BadRequestResponseResponse,
    403: NotAuthorizedResponseResponse,
    429: TooManyRequestsResponseResponse,
  },
})

