export const getApiV2SecuritySbomsRoute = createRoute({
  method: 'get',
  path: '/api/v2/security/sboms',
  tags: ['Security Monitoring'],
  summary: 'List assets SBOMs',
  description:
    'Get a list of assets SBOMs for an organization.\n\nThe `filter[asset_type]` parameter is required for initial requests (when no `page[token]` is provided).\nSubsequent pages encode the asset type in the pagination token, so `filter[asset_type]` is not required\nfor paginated requests. Mixing infrastructure asset types (`Host`, `HostImage`, `Image`, `ServerlessFunction`)\nwith code asset types (`Repository`, `Service`) in the same request is not supported and returns a 400 error.\n\n### Pagination\n\nPlease review the [Pagination section](#pagination) for the "List Vulnerabilities" endpoint.\n\n### Filtering\n\nPlease review the [Filtering section](#filtering) for the "List Vulnerabilities" endpoint.\n\n### Metadata\n\nPlease review the [Metadata section](#metadata) for the "List Vulnerabilities" endpoint.',
  operationId: 'ListAssetsSBOMs',
  request: {
    query: z.object({
      'page[token]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Its value must come from the `links` section of the response of the first request. Do not manually edit it.',
            example:
              'b82cef018aab81ed1d4bb4xb35xxfc065da7efa685fbcecdbd338f3015e3afabbbfa3a911b4984_721ee28a-zecb-4e45-9960-c42065b574f4',
            in: 'query',
            name: 'page[token]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'page[number]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(1n))
        .exactOptional()
        .openapi({
          param: {
            description:
              'The page number to be retrieved. It should be equal to or greater than 1.',
            example: 1,
            in: 'query',
            name: 'page[number]',
            required: false,
            schema: { format: 'int64', minimum: 1, type: 'integer' },
          },
        }),
      'filter[asset_type]': AssetTypeSchema.openapi({
        param: {
          description:
            'The type of the assets for the SBOM request. Required for initial requests (when no `page[token]` is provided). Infrastructure types (`Host`, `HostImage`, `Image`, `ServerlessFunction`) and code types (`Repository`, `Service`) cannot be mixed in the same request.',
          example: 'Repository',
          in: 'query',
          name: 'filter[asset_type]',
          required: false,
          schema: { $ref: '#/components/schemas/AssetType' },
        },
      }).exactOptional(),
      'filter[asset_name]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The name of the asset for the SBOM request.',
            example: 'github.com/datadog/datadog-agent',
            in: 'query',
            name: 'filter[asset_name]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[package_name]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The name of the component that is a dependency of an asset.',
            example: 'opentelemetry-api',
            in: 'query',
            name: 'filter[package_name]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[package_version]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The version of the component that is a dependency of an asset.',
            example: '1.33.1',
            in: 'query',
            name: 'filter[package_version]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[license_name]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'The software license name of the component that is a dependency of an asset.',
            example: 'Apache-2.0',
            in: 'query',
            name: 'filter[license_name]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[license_type]': SBOMComponentLicenseTypeSchema.openapi({
        param: {
          description:
            'The software license type of the component that is a dependency of an asset.',
          example: 'network_strong_copyleft',
          in: 'query',
          name: 'filter[license_type]',
          required: false,
          schema: { $ref: '#/components/schemas/SBOMComponentLicenseType' },
        },
      }).exactOptional(),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: ListAssetsSBOMsResponseSchema,
          examples: { default: { value: { data: [] } } },
        },
      },
    },
    400: {
      description:
        'Bad request: The server cannot process the request due to invalid syntax in the request.',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    403: {
      description: 'Forbidden: Access denied',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    404: {
      description: 'Not found: asset not found',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: [] }],
})

