export const getApiV2SecurityScannedAssetsMetadataRoute = createRoute({
  method: 'get',
  path: '/api/v2/security/scanned-assets-metadata',
  tags: ['Security Monitoring'],
  summary: 'List scanned assets metadata',
  description:
    'Get a list of security scanned assets metadata for an organization.\n\n### Pagination\n\nFor the "List Vulnerabilities" endpoint, see the [Pagination section](#pagination).\n\n### Filtering\n\nFor the "List Vulnerabilities" endpoint, see the [Filtering section](#filtering).\n\n### Metadata\n\n For the "List Vulnerabilities" endpoint, see the [Metadata section](#metadata).\n\n### Related endpoints\n\nThis endpoint returns additional metadata for cloud resources that is not available from the standard resource endpoints. To access a richer dataset, call this endpoint together with the relevant resource endpoint(s) and merge (join) their results using the resource identifier.\n\n**Hosts**\n\nTo enrich host data, join the response from the [Hosts](https://docs.datadoghq.com/api/latest/hosts/) endpoint with the response from the scanned-assets-metadata endpoint on the following key fields:\n\n| ENDPOINT | JOIN KEY | TYPE |\n| --- | --- | --- |\n| [/api/v1/hosts](https://docs.datadoghq.com/api/latest/hosts/) | host_list.host_name | string |\n| /api/v2/security/scanned-assets-metadata | data.attributes.asset.name | string |\n\n**Host Images**\n\nTo enrich host image data, join the response from the [Hosts](https://docs.datadoghq.com/api/latest/hosts/) endpoint with the response from the scanned-assets-metadata endpoint on the following key fields:\n\n| ENDPOINT | JOIN KEY | TYPE |\n| --- | --- | --- |\n| [/api/v1/hosts](https://docs.datadoghq.com/api/latest/hosts/) | host_list.tags_by_source["Amazon Web Services"]["image"] | string |\n| /api/v2/security/scanned-assets-metadata | data.attributes.asset.name | string |\n\n**Container Images**\n\nTo enrich container image data, join the response from the [Container Images](https://docs.datadoghq.com/api/latest/container-images/) endpoint with the response from the scanned-assets-metadata endpoint on the following key fields:\n\n| ENDPOINT | JOIN KEY | TYPE |\n| --- | --- | --- |\n| [/api/v2/container_images](https://docs.datadoghq.com/api/latest/container-images/) | `data.attributes.name`@`data.attributes.repo_digest` | string |\n| /api/v2/security/scanned-assets-metadata | data.attributes.asset.name | string |',
  operationId: 'ListScannedAssetsMetadata',
  request: {
    query: z.object({
      'page[token]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Its value must come from the `links` section of the response of the first request. Do not manually edit it.',
            example:
              'b82cef018aab81ed1d4bb4xb35xxfc065da7efa685fbcecdbd338f3015e3afabbbfa3a911b4984_721ee28a-zecb-4e45-9960-c42065b574f4',
            in: 'query',
            name: 'page[token]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'page[number]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(1n))
        .exactOptional()
        .openapi({
          param: {
            description:
              'The page number to be retrieved. It should be equal to or greater than 1.',
            example: 1,
            in: 'query',
            name: 'page[number]',
            required: false,
            schema: { format: 'int64', minimum: 1, type: 'integer' },
          },
        }),
      'filter[asset.type]': CloudAssetTypeSchema.openapi({
        param: {
          description: 'The type of the scanned asset.',
          example: 'Host',
          in: 'query',
          name: 'filter[asset.type]',
          required: false,
          schema: { $ref: '#/components/schemas/CloudAssetType' },
        },
      }).exactOptional(),
      'filter[asset.name]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The name of the scanned asset.',
            example: 'i-0fc7edef1ab26d7ef',
            in: 'query',
            name: 'filter[asset.name]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[last_success.origin]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The origin of last success scan.',
            example: 'agent',
            in: 'query',
            name: 'filter[last_success.origin]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[last_success.env]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The environment of last success scan.',
            example: 'prod',
            in: 'query',
            name: 'filter[last_success.env]',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: ScannedAssetsMetadataSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      asset: { name: 'i-0fc7edef1ab26d7ef', type: 'Host' },
                      first_success_timestamp: '2024-01-01T00:00:00Z',
                      last_success: { env: 'prod' },
                    },
                    id: 'Host|i-0fc7edef1ab26d7ef',
                    type: 'scanned-assets-metadata',
                  },
                ],
              },
            },
          },
        },
      },
    },
    400: {
      description:
        'Bad request: The server cannot process the request due to invalid syntax in the request.',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    403: {
      description: 'Forbidden: Access denied',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    404: {
      description: 'Not found: asset not found',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: [] }],
})

