export const postApiV2SecurityVulnerabilitiesRoute = createRoute({
  method: 'post',
  path: '/api/v2/security/vulnerabilities',
  tags: ['Security Monitoring'],
  summary: 'Import security vulnerabilities',
  description:
    'Import security vulnerabilities from an external scanner in CycloneDX 1.5 format.\n\nThe payload is validated against the CycloneDX 1.5 JSON schema and the following\nadditional constraints:\n\n- `metadata`, `metadata.component`, and `metadata.component.name` are required.\n- `metadata.tools.components` must contain exactly one element with a `name` field.\n- `components` cannot be empty. Each component requires `bom-ref`, `type`, `name`, and `version`.\n- When `type` is `library`, `purl` is required and must be a valid PURL.\n- When `type` is `operating-system`, `name` must be one of the supported OS values:\n  `alma`, `alpine`, `amazon`, `azurelinux`, `bottlerocket`, `cbl-mariner`, `chainguard`,\n  `centos`, `debian`, `fedora`, `opensuse`, `opensuse-leap`, `opensuse-tumbleweed`,\n  `oracle`, `photon`, `redhat`, `rocky`, `slem`, `sles`, `ubuntu`, `wolfi`, `windows`, `macos`.\n- `vulnerabilities` cannot be empty. Each vulnerability requires `id`, exactly one `ratings` entry,\n  and at least one `affects` entry.\n- Each `affects[].ref` must match a `bom-ref` value in `components`.',
  operationId: 'ImportSecurityVulnerabilities',
  request: {
    body: {
      content: {
        'application/json': {
          schema: CycloneDXBomSchema,
          examples: {
            default: {
              value: {
                bomFormat: 'CycloneDX',
                components: [
                  {
                    'bom-ref': 'a3390fca-c315-41ae-ae05-af5e7859cdee',
                    name: 'lodash',
                    purl: 'pkg:npm/lodash@4.17.21',
                    type: 'library',
                    version: '4.17.21',
                  },
                ],
                metadata: {
                  component: { name: 'i-12345', type: 'operating-system' },
                  tools: { components: [{ name: 'my-scanner', type: 'application' }] },
                },
                specVersion: '1.5',
                version: 1,
                vulnerabilities: [
                  {
                    affects: [{ ref: 'a3390fca-c315-41ae-ae05-af5e7859cdee' }],
                    description: 'Sample vulnerability detected in the application.',
                    id: 'CVE-2021-1234',
                    ratings: [
                      {
                        score: 9,
                        severity: 'high',
                        vector: 'CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:C/C:H/I:H/A:N',
                      },
                    ],
                  },
                ],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: { description: 'Vulnerabilities accepted successfully.' },
    400: BadRequestResponseResponse,
    403: ForbiddenResponseResponse,
    429: TooManyRequestsResponseResponse,
    500: {
      description: 'Internal Server Error',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['security_monitoring_findings_write'] }],
})

