export const getApiV2SecurityMonitoringConfigurationSuppressionsRoute = createRoute({
  method: 'get',
  path: '/api/v2/security_monitoring/configuration/suppressions',
  tags: ['Security Monitoring'],
  summary: 'Get all suppression rules',
  description: 'Get the list of all suppression rules.',
  operationId: 'ListSecurityMonitoringSuppressions',
  request: {
    query: z.object({
      query: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Query string.',
            in: 'query',
            name: 'query',
            required: false,
            schema: { type: 'string' },
          },
        }),
      sort: SecurityMonitoringSuppressionSortSchema.openapi({
        param: {
          description:
            'Attribute used to sort the list of suppression rules. Prefix with `-` to sort in descending order.',
          in: 'query',
          name: 'sort',
          required: false,
          schema: { $ref: '#/components/schemas/SecurityMonitoringSuppressionSort' },
        },
      }).exactOptional(),
      'page[size]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(-1n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Size for a given page. Use `-1` to return all items.',
            in: 'query',
            name: 'page[size]',
            required: false,
            schema: { default: -1, example: 10, format: 'int64', type: 'integer' },
          },
          example: 10,
        }),
      'page[number]': PageNumberParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: SecurityMonitoringPaginatedSuppressionsResponseSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      editable: true,
                      enabled: true,
                      name: 'Custom suppression',
                      rule_query: 'type:log_detection source:cloudtrail',
                      suppression_query: 'env:staging status:low',
                      version: 1,
                    },
                    id: '3dd-0uc-h1s',
                    type: 'suppressions',
                  },
                ],
                meta: { page: { pageNumber: 0, pageSize: 10, totalCount: 1 } },
              },
            },
          },
        },
      },
    },
    403: NotAuthorizedResponseResponse,
    429: TooManyRequestsResponseResponse,
  },
  security: [
    { apiKeyAuth: [], appKeyAuth: [] },
    { AuthZ: ['security_monitoring_suppressions_read'] },
  ],
})

