export const getApiV2SecurityMonitoringSignalsSignalIdEntitiesRoute = createRoute({
  method: 'get',
  path: '/api/v2/security_monitoring/signals/{signal_id}/entities',
  tags: ['Security Monitoring'],
  summary: 'Get entities related to a signal',
  description:
    "Get the list of entities related to a security signal, captured at the signal's timestamp.",
  operationId: 'GetSignalEntities',
  request: {
    params: z.object({ signal_id: SignalIDParamsSchema }),
    query: z.object({
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().max(1000),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of entities to return.',
            in: 'query',
            name: 'limit',
            required: false,
            schema: { default: 10, example: 10, format: 'int32', maximum: 1000, type: 'integer' },
          },
          example: 10,
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: SignalEntitiesResponseSchema,
          examples: {
            default: {
              value: {
                data: {
                  attributes: {
                    identities: [{ display_name: 'Test User', principal_id: 'user@example.com' }],
                  },
                  id: 'AAAAAWgN8Xwgr1vKDQAAAABBV2dOOFh3ZzZobm1mWXJFYTR0OA',
                  type: 'entities',
                },
              },
            },
          },
        },
      },
    },
    400: BadRequestResponseResponse,
    403: NotAuthorizedResponseResponse,
    404: NotFoundResponseResponse,
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['security_monitoring_signals_read'] }],
})

