export const postApiV2SeriesRoute = createRoute({
  method: 'post',
  path: '/api/v2/series',
  tags: ['Metrics'],
  summary: 'Submit metrics',
  description:
    'The metrics end-point allows you to post time-series data that can be graphed on Datadog’s dashboards.\nThe maximum payload size is 500 kilobytes (512000 bytes). Compressed payloads must have a decompressed size of less than 5 megabytes (5242880 bytes).\n\nIf you’re submitting metrics directly to the Datadog API without using DogStatsD, expect:\n\n- 64 bits for the timestamp\n- 64 bits for the value\n- 20 bytes for the metric names\n- 50 bytes for the timeseries\n- The full payload is approximately 100 bytes.\n\nHost name is one of the resources in the Resources field.',
  operationId: 'SubmitMetrics',
  request: {
    headers: z.object({
      'Content-Encoding': MetricContentEncodingSchema.openapi({
        param: {
          description: 'HTTP header used to compress the media-type.',
          in: 'header',
          name: 'Content-Encoding',
          required: false,
          schema: { $ref: '#/components/schemas/MetricContentEncoding' },
        },
      }).exactOptional(),
    }),
    body: {
      content: {
        'application/json': {
          schema: MetricPayloadSchema,
          examples: {
            default: {
              value: {
                series: [
                  {
                    metric: 'system.load.1',
                    points: [{ timestamp: 1636629071, value: 1.1 }],
                    resources: [{ name: 'dummyhost', type: 'host' }],
                    type: 0,
                  },
                ],
              },
            },
            'dynamic-points': {
              summary: 'Dynamic Points',
              description: 'Post time-series data that can be graphed on Datadog’s dashboards.',
              externalValue: 'examples/metrics/dynamic-points.json.sh',
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    202: {
      description: 'Payload accepted',
      content: {
        'application/json': {
          schema: IntakePayloadAcceptedSchema,
          examples: { default: { value: { errors: [] } } },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
    403: {
      description: 'Authentication error',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
    408: {
      description: 'Request timeout',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
    413: {
      description: 'Payload too large',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [] }],
})

