export const getApiV2StatuspagesRoute = createRoute({
  method: 'get',
  path: '/api/v2/statuspages',
  tags: ['Status Pages'],
  summary: 'List status pages',
  description: 'Lists all status pages for the organization.',
  operationId: 'ListStatusPages',
  request: {
    query: z.object({
      'page[offset]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Offset to use as the start of the page.',
            in: 'query',
            name: 'page[offset]',
            schema: { default: 0, format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      'page[limit]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(50n)
        .exactOptional()
        .openapi({
          param: {
            description: 'The number of status pages to return per page.',
            in: 'query',
            name: 'page[limit]',
            schema: { default: 50, format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      'filter[domain_prefix]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter status pages by exact domain prefix match. Returns at most one result.',
            in: 'query',
            name: 'filter[domain_prefix]',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'filter[name]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter status pages by name with case-insensitive substring matching.',
            in: 'query',
            name: 'filter[name]',
            schema: { type: 'string' },
            required: false,
          },
        }),
      include: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Comma-separated list of resources to include. Supported values: created_by_user, last_modified_by_user.',
            in: 'query',
            name: 'include',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: StatusPageArraySchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      components: [],
                      domain_prefix: 'status-page-us1',
                      enabled: true,
                      name: 'Status Page US1',
                      subscriptions_enabled: true,
                      type: 'public',
                      visualization_type: 'bars_and_uptime_percentage',
                    },
                    id: '00000000-0000-0000-0000-000000000001',
                    type: 'status_pages',
                  },
                ],
              },
            },
          },
        },
      },
    },
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['status_pages_settings_read'] }],
})

