export const getApiV2SyntheticsTestsPublicIdVersionHistoryRoute = createRoute({
  method: 'get',
  path: '/api/v2/synthetics/tests/{public_id}/version_history',
  tags: ['Synthetics'],
  summary: 'Get version history of a test',
  description: 'Get the paginated version history for a Synthetic test.',
  operationId: 'ListSyntheticsTestVersions',
  request: {
    params: z.object({
      public_id: z
        .string()
        .openapi({
          param: {
            description: 'The public ID of the Synthetic test.',
            in: 'path',
            name: 'public_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      last_version_number: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description:
              'The version number of the last item from the previous page. Omit to get the first page.',
            in: 'query',
            name: 'last_version_number',
            required: false,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().max(50n))
        .exactOptional()
        .openapi({
          param: {
            description: 'Maximum number of version records to return per page.',
            in: 'query',
            name: 'limit',
            required: false,
            schema: { format: 'int64', maximum: 50, type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: SyntheticsTestVersionHistoryResponseSchema,
          examples: { default: { value: { data: [] } } },
        },
      },
    },
    403: {
      description: 'API error response.',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
    404: {
      description: 'API error response.',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['synthetics_read'] }],
})

