export const getApiV2UsageQuotasQuotaNamespaceRoute = createRoute({
  method: 'get',
  path: '/api/v2/usage/quotas/{quota_namespace}',
  tags: ['Usage Metering'],
  summary: 'List usage quotas',
  description:
    "Lists usage quotas for the caller's organization in a quota namespace. You can optionally include\ndescendant organizations in the same datacenter as the caller. Requires the `billing_read` or\n`billing_edit` permission.",
  operationId: 'ListQuotas',
  request: {
    params: z.object({
      quota_namespace: z
        .string()
        .openapi({
          param: {
            description: 'The product-specific namespace whose usage quotas are being managed.',
            in: 'path',
            name: 'quota_namespace',
            required: true,
            schema: { example: 'ai_credits', type: 'string' },
          },
          example: 'ai_credits',
        }),
    }),
    query: z.object({
      include_descendants: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description:
              "Whether to include quotas configured on descendant organizations in the caller's organization hierarchy. Only descendants in the same datacenter are supported.",
            in: 'query',
            name: 'include_descendants',
            required: false,
            schema: { default: false, type: 'boolean' },
          },
        }),
      'page[cursor]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              "An opaque cursor from a previous response's `meta.page.next_cursor` used to retrieve the next page.",
            in: 'query',
            name: 'page[cursor]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'page[limit]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(1n).max(1000n))
        .default(100n)
        .exactOptional()
        .openapi({
          param: {
            description: 'The number of usage quotas to return per page.',
            in: 'query',
            name: 'page[limit]',
            required: false,
            schema: { default: 100, format: 'int64', maximum: 1000, minimum: 1, type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: UsageQuotasListResponseSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      enforced: true,
                      org_public_id: 'abcdef12345',
                      scope: { user_handle: 'jane@example.com' },
                      usage_limit: 100000,
                    },
                    id: 'MTIzNB9haV9jcmVkaXRzH3VzZXJfaGFuZGxlOmphbmVAZXhhbXBsZS5jb20',
                    type: 'quotas',
                  },
                  {
                    attributes: {
                      enforced: true,
                      org_public_id: 'abcdef12345',
                      pending_effective_from: '2026-11',
                      pending_usage_limit: 100000,
                      usage_limit: 600000,
                    },
                    id: 'MTIzNB9haV9jcmVkaXRzH3VzZXJfaGFuZGxlOl9fQUxMX18',
                    type: 'quotas',
                  },
                ],
                meta: { page: { next_cursor: 'eyJvZmZzZXQiOjEwMH0=' } },
              },
            },
          },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    403: {
      description: 'Forbidden',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
  },
  security: [
    { apiKeyAuth: [], appKeyAuth: [] },
    { AuthZ: ['billing_read'] },
    { AuthZ: ['billing_edit'] },
  ],
})

export const postApiV2UsageQuotasQuotaNamespaceRoute = createRoute({
  method: 'post',
  path: '/api/v2/usage/quotas/{quota_namespace}',
  tags: ['Usage Metering'],
  summary: 'Create or update usage quotas',
  description:
    'Creates or updates one or more usage quotas by scope. If a quota already exists for a supplied scope, it is updated.\nOtherwise, a quota is created only when `usage_limit` and `enforced` are provided.\nFor the organization-wide quota, `pending_usage_limit` schedules a limit for the next usage period and can\naccompany an immediate limit or update an existing quota by itself.\nScheduled changes follow `include_descendants` like the other fields. Requires the `billing_edit` permission.',
  operationId: 'CreateQuotas',
  request: {
    params: z.object({
      quota_namespace: z
        .string()
        .openapi({
          param: {
            description: 'The product-specific namespace whose usage quotas are being managed.',
            in: 'path',
            name: 'quota_namespace',
            required: true,
            schema: { example: 'ai_credits', type: 'string' },
          },
          example: 'ai_credits',
        }),
    }),
    query: z.object({
      include_descendants: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description:
              "Whether to write every item in the request to the caller's organization and all of its descendant organizations, instead of only the caller's organization. Only descendants in the same datacenter are supported. For a user-handle scope, the quota is applied only to the caller's organization and to descendant organizations where that user handle exists; the item fails only if the handle exists in none of them.",
            in: 'query',
            name: 'include_descendants',
            required: false,
            schema: { default: false, type: 'boolean' },
          },
        }),
    }),
    body: {
      description: 'The usage quotas to create or update.',
      content: {
        'application/json': {
          schema: UsageQuotasCreateRequestSchema,
          examples: {
            default: {
              summary: "Create or update quotas for the caller's organization.",
              value: {
                data: [
                  {
                    attributes: {
                      enforced: true,
                      scope: { user_handle: 'jane@example.com' },
                      usage_limit: 100000,
                    },
                    type: 'quotas',
                  },
                  {
                    attributes: {
                      enforced: false,
                      scope: { user_handle: '*' },
                      usage_limit: 250000,
                    },
                    type: 'quotas',
                  },
                ],
              },
            },
            schedule_reduction: {
              summary: 'Set a limit and schedule a reduction',
              value: {
                data: [
                  {
                    attributes: {
                      enforced: true,
                      pending_usage_limit: 100000,
                      usage_limit: 600000,
                    },
                    type: 'quotas',
                  },
                ],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description:
        "OK. The response includes each item's result; see each item's `error` attribute for any that failed to write.",
      content: {
        'application/json': {
          schema: UsageQuotasBulkResponseSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      enforced: true,
                      org_public_id: 'abcdef12345',
                      scope: { user_handle: 'jane@example.com' },
                      usage_limit: 100000,
                    },
                    id: 'MTIzNB9haV9jcmVkaXRzH3VzZXJfaGFuZGxlOmphbmVAZXhhbXBsZS5jb20',
                    type: 'quotas',
                  },
                  {
                    attributes: { error: 'usage_limit is out of range' },
                    id: 'MTIzNB9haV9jcmVkaXRzH3VzZXJfaGFuZGxlOnVzZXJAZXhhbXBsZS5jb20',
                    type: 'quotas',
                  },
                ],
              },
            },
          },
        },
      },
    },
    400: {
      description:
        "Bad Request. Returned if the request is malformed, including when an item sets `pending_usage_limit` on a scoped quota, provides `enforced` without `usage_limit`, or provides neither limit. A pending-only item for a quota that does not exist is reported in that item's `error`; when only the caller's organization is targeted, this failure returns `400`.",
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    403: {
      description: 'Forbidden',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
    500: {
      description: 'Internal Server Error. Every item in the batch failed to write.',
      content: { 'application/json': { schema: JSONAPIErrorResponseSchema } },
    },
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: ['billing_edit'] }],
})

