export const getApiV2WidgetsExperienceTypeRoute = createRoute({
  method: 'get',
  path: '/api/v2/widgets/{experience_type}',
  tags: ['Widgets'],
  summary: 'Search widgets',
  description:
    "Search and list widgets for a given experience type, with filtering, sorting, and pagination.\n\n**Response meta** carries totals scoped to the current filter:\n- `filtered_total` — widgets matching the filter.\n- `created_by_you_total` — among the matches, how many the current user created.\n- `favorited_by_you_total` — among the matches, how many the current user has favorited.\n- `created_by_anyone_total` — total widgets in the experience type, ignoring filters.\n\nEach returned widget includes `is_favorited` reflecting the current user's favorite status.\nFavoriting itself is performed through the shared favorites API, not this endpoint.",
  operationId: 'SearchWidgets',
  request: {
    params: z.object({
      experience_type: WidgetExperienceTypeSchema.openapi({
        param: {
          description: 'The experience type for the widget.',
          in: 'path',
          name: 'experience_type',
          required: true,
          schema: { $ref: '#/components/schemas/WidgetExperienceType' },
        },
      }),
    }),
    query: z.object({
      'filter[widgetType]': WidgetTypeSchema.openapi({
        param: {
          description: 'Filter widgets by widget type.',
          in: 'query',
          name: 'filter[widgetType]',
          schema: { $ref: '#/components/schemas/WidgetType' },
          required: false,
        },
      }).exactOptional(),
      'filter[creatorHandle]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter widgets by the email handle of the creator.',
            in: 'query',
            name: 'filter[creatorHandle]',
            schema: { example: 'john.doe@example.com', type: 'string' },
            required: false,
          },
          example: 'john.doe@example.com',
        }),
      'filter[isFavorited]': z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter to only widgets favorited by the current user.',
            in: 'query',
            name: 'filter[isFavorited]',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      'filter[title]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter widgets by title (substring match).',
            in: 'query',
            name: 'filter[title]',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'filter[tags]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter widgets by tags. Format as bracket-delimited CSV, e.g. `[tag1,tag2]`.',
            in: 'query',
            name: 'filter[tags]',
            schema: { type: 'string' },
            required: false,
          },
        }),
      sort: z
        .string()
        .default('-modified_at')
        .exactOptional()
        .openapi({
          param: {
            description:
              'Sort field for the results.\n\n**`title`, `created_at`, `modified_at`** — both ascending and descending are\nsupported. Use the bare field name for ascending (e.g. `sort=title`) or prefix\nwith `-` for descending (e.g. `sort=-modified_at`).\n\n**`is_favorited`** — returns favorites-first ordering (favorited widgets first,\nthen the rest). Direction is fixed; the `-` prefix is ignored for this field.',
            in: 'query',
            name: 'sort',
            schema: { default: '-modified_at', example: '-modified_at', type: 'string' },
            required: false,
          },
          example: '-modified_at',
        }),
      'page[number]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().min(0n))
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Page number for pagination (0-indexed).',
            in: 'query',
            name: 'page[number]',
            schema: { default: 0, format: 'int64', minimum: 0, type: 'integer' },
            required: false,
          },
        }),
      'page[size]': z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().max(100n))
        .default(50n)
        .exactOptional()
        .openapi({
          param: {
            description: 'Number of widgets per page.',
            in: 'query',
            name: 'page[size]',
            schema: { default: 50, format: 'int64', maximum: 100, type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: WidgetListResponseSchema,
          examples: { default: { value: { data: [] } } },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
    403: {
      description: 'Forbidden',
      content: { 'application/json': { schema: APIErrorResponseSchema } },
    },
    429: TooManyRequestsResponseResponse,
  },
  security: [{ apiKeyAuth: [], appKeyAuth: [] }, { AuthZ: [] }],
})

