export const getApiV2WorkflowsRoute = createRoute({
  method: 'get',
  path: '/api/v2/workflows',
  tags: ['Workflow Automation'],
  summary: 'List workflows',
  description:
    'List all workflows in your organization. This API requires a [registered application key](https://docs.datadoghq.com/api/latest/action-connection/#register-a-new-app-key). Alternatively, you can configure these permissions [in the UI](https://docs.datadoghq.com/account_management/api-app-keys/#actions-api-access).',
  operationId: 'ListWorkflows',
  request: {
    query: z.object({
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(50n)
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of workflows to return per page.',
            example: 50,
            in: 'query',
            name: 'limit',
            required: false,
            schema: { default: 50, format: 'int64', type: 'integer' },
          },
        }),
      page: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description: 'The page number to return, starting from 0.',
            example: 0,
            in: 'query',
            name: 'page',
            required: false,
            schema: { default: 0, format: 'int64', type: 'integer' },
          },
        }),
      sort: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'The sort order for the returned workflows. Provide a comma-separated list of fields, each optionally prefixed with `-` for descending order. Supported fields are `name`, `createdAt`, `updatedAt`, `creatorName`, `ownerName`, and `lastExecutedAt`.',
            example: '-updatedAt',
            in: 'query',
            name: 'sort',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[query]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              "A search query used to filter the returned workflows. The query performs a case-insensitive substring match against each workflow's name, creator name, and handle. If the query contains a colon (for example, `team:infra`), the query is treated as a `key:value` tag filter.",
            example: 'deploy',
            in: 'query',
            name: 'filter[query]',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'filter[triggerIds]': z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filters the returned workflows by one or more trigger types, such as `monitor`, `schedule`, or `githubWebhook`. To specify the multiple types, repeat this parameter.',
            example: ['monitor'],
            explode: true,
            in: 'query',
            name: 'filter[triggerIds]',
            required: false,
            schema: { items: { type: 'string' }, type: 'array' },
          },
        }),
      'filter[includeUnpublished]': z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description: 'Whether to include unpublished workflows in the response.',
            in: 'query',
            name: 'filter[includeUnpublished]',
            required: false,
            schema: { default: false, type: 'boolean' },
          },
        }),
      'filter[includeSpecs]': z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description:
              "Whether to include the full spec of each workflow in the response. When `false` (the default), each workflow's `spec` is returned as `null`.",
            in: 'query',
            name: 'filter[includeSpecs]',
            required: false,
            schema: { default: false, type: 'boolean' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: ListWorkflowsResponseSchema,
          examples: {
            default: {
              value: {
                data: [
                  {
                    attributes: {
                      createdAt: '2024-01-01T00:00:00+00:00',
                      description: 'A sample workflow.',
                      name: 'Example Workflow',
                      published: true,
                      runAsUserMode: 'owner',
                      spec: {},
                      tags: ['team:infra'],
                      updatedAt: '2024-01-01T00:00:00+00:00',
                    },
                    id: '00000000-0000-0000-0000-000000000002',
                    relationships: {
                      creator: {
                        data: { id: '00000000-0000-0000-0000-000000000009', type: 'users' },
                      },
                      owner: {
                        data: { id: '00000000-0000-0000-0000-000000000009', type: 'users' },
                      },
                    },
                    type: 'workflows',
                  },
                ],
                meta: { page: { totalCount: 1, totalFilteredCount: 1 } },
              },
            },
          },
        },
      },
    },
    400: BadRequestResponseResponse,
    403: ForbiddenResponseResponse,
    429: TooManyRequestsResponseResponse,
  },
})

